comms.text:
@1 וְאַתְּ תְּפַקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מִשְׁחָא זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@2 בְּמַשְׁכַּן זִמְנָא מִבָּרָא לְפָרֻכְתָּא דְעַל סַהֲדוּתָא יְסַדַר יָתֵהּ אַהֲרֹן וּבְנוֹהִי מֵרַמְשָׁא עַד צַפְרָא קָדָם יְיָ קְיָם עֲלָם לְדָרֵיהוֹן מִן בְּנֵי יִשְׂרָאֵל:וְ
@3 אַתְּ קָרֵב לְוָתָךְ יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ מִגוֹ בְּנֵי יִשְׂרָאֵל לְשַׁמָשָׁא קֳדָמַי אַהֲרֹן נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר בְּנֵי אַהֲרֹן:
@4 וְתַעְבֵּד לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ לִיקָר וּלְתֻשְׁבְּחָן:
@5 וְאַתְּ תְּמַלֵל עִם כָּל חַכִּימֵי לִבָּא דְאַשְׁלֵמִית עִמֵהּ רוּחַ חָכְמְתָא וְיַעְבְּדוּן יָת לְבוּשֵׁי אַהֲרֹן לְקַדָשׁוּתֵהּ לְשַׁמָשָׁא קֳדָמַי:
@6 וְאִלֵין לְבוּשַׁיָא דִי יַעְבְּדוּן חוּשְׁנָא וְאֵפוֹדָא וּמְעִילָא וְכִתּוּנָא מְרַמְצָא מִצְנֶפְתָּא וְהֶמְיָנָא וְיַעְבְּדוּן לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ וְלִבְנוֹהִי לְשַׁמָשָׁא קֳדָמַי:
@7 וְאִנוּן יִסְבוּן יָת דַהֲבָא וְיָת תִּכְלָא וְיָת אַרְגְוָנָא וְיָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@8 וְיַעְבְּדוּן יָת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא צְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן:
@9 תַּרְתֵּין כַּתְפִּין מְלַפְּפָן יְהוֹן לֵהּ עַל תְּרֵין סִטְרוֹהִי וְיִתְלָפַף:
@10 וְהֶמְיַן תִּקוּנֵי דִי עֲלוֹהִי כְּעוֹבָדוֹהִי מִנֵהּ יְהֵי דַהֲבָא תִּכְלָא וְאַרְגְּוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@11 וְתִסַב יָת תַּרְתֵּין אַבְנֵי בוּרְלָא וְתִגְלוֹף עֲלֵיהֶן שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@12 שִׁתָּא מִשְׁמָהָתְהוֹן עַל אַבְנָא חֲדָא וְיָת שְׁמָהַת שִׁתָּא דְאִשְׁתָּאָרוּ עַל אַבְנָא תִנְיֵתָא כְּתוּלְדָתְהוֹן:
@13 עוֹבַד אֳמָן אֶבֶן טָבָא כְּתַב מְפָרַשׁ כִּגְלֹף דְעִזְקָא תִגְלוֹף יָת תַּרְתֵּין אַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל מְשַׁקְעָן מְרַמְצָן דִדְהַב תַּעְבֵּד יָתְהוֹן:
@14 וּתְשַׁוִּי יָת תַּרְתֵּין אַבְנַיָא עַל כִּתְפֵּי אֵפוֹדָא אַבְנֵי דָכְרָנָא לִבְנֵי יִשְׂרָאֵל וְיִטּוֹל אַהֲרֹן יָת שְׁמָהָתְהוֹן קֳדָם יְיָ עַל תְּרֵין כִּתְפּוֹהִי לְדָכְרָנָא:
@15 וְתַעְבֵּד מְרַמְצָן דִדְהַב:
@16 וְתַרְתֵּין תִּכִּין דְהַב דְכֵי מְתַחְמָן תַּעְבֵד יָתְהוֹן עוֹבַד גְדִילוּ וְתִתֵּן יָת תִּכַּיָא גְדִילָתָא עַל מְרַמְצָתָא:
@17 וְתַעְבֵּד חשֶׁן דִינָא עוֹבַד אֳמָן כְּעוֹבַד אֵפוֹדָא תַּעְבְּדִנֵהּ דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר תַּעְבֵּד יָתֵהּ:
@18 מְרַבַּע יְהֵי עֵיף זֶרְתָּא אֻרְכֵּה וְזֶרְתָּא פְתָיֵהּ:
@19 וְתַשְׁלֵם בֵּה אַשְׁלָמוּת אַבְנָא אַרְבְּעָא סִדְרִין אֶבֶן טָּבָא סִדְרָא קַדְמָאָה םַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@20 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין וְשַׁבְזִיז וְסִבְהֲלוֹם:
@21 וְסִדְרָא תְּלִיתָאָה קַנְכִּירֵי טַרְקְיָא וְעֵין עֶגְלָא:
@22 וְסִדְרֵא רְבִיעָאָה כְּרוּם יַמָא וּבוּרְלָא וּפַנְטֵרֵי מְרַמְצָן דִדְהַב יְהוֹן בְּאַשְׁלָמוּתְהוֹן:
@23 וְאַבְנַיָא יְהֶוְיַן עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ תְּהֶוְיָן לִתְרֵין עֲסַר שִׁבְטִין:
@24 וְתַעְבֵּד עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@25 וְתַעְבֵּד עַל חוּשְׁנָא תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@26 וְתִתֵּן יָת תַּרְתֵּין גְדִילָן דִדְהַב עַל תַּרְתֵּין עִזְקָתָא לְסִטְרֵי חוּשְׁנָא:
@27 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי תִּתֵּן עַל תַּרְתֵּין מְרַמְצָתָא וְתִתֵּן עַל כִּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@28 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וּתְשַׁוִּי יָתְהוֹן עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָו:
@29 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָתְהוֹן עַל תַּרְתֵּין כִּתְפֵּי אֵפוֹדָא מִלְרַע מִלְקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@30 וְיֶחְדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקְתָא דְאֵפוֹדָא בְּחוּטָא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא:
@31 וְיִטוֹל אַהֲרֹן יָת שְׁמָהַת בְּנֵי יִשְׂרָאֵל בְּחשֶׁן דִינָא עַל לִבֵּהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא לְדוּכְרָנָא קֳדָם יְיָ תְּדִירָא:
@32 וְתִתֵּן בְּחשֶׁן דִינָא יָת אוּרַיָא וְיָת תֻּמַיָא וִיהוֹן עַל לִבָּא דְאַהֲרֹן בְּמֵעֲלֵהּ קֳדָם יְיָ וְיִטוֹל אַהֲרֹן יָת דִינָא דִבְנֵי יִשְׂרָאֵל עַל לִבֵּהּ קֳדָם יְיָ תְּדִירָא:
@33 וְתַעְבֵּד יָת מְעִילָא דְאֵפוֹדָא גְמִיר תִּכְלָא:
@34 וִיהֵי פוּם רֵישֵׁהּ כָּפִיל לְגַוֵּהּ תּוֹרָא יְהֵא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר עוֹבַד מָחֵי כְּפוּם שִׂרְיָן יְהֵי לֵהּ לָא יִתְבְּזָע:
@35 וְתַעְבֵּד עַל שִׁיפוֹלוֹהִי רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עַל שִׁיפוֹלוֹהִי סְחוֹר סְחוֹר וְזַגִין דְדַהֲבָא בֵּינֵיהוֹן סְחוֹר סְחוֹר:
@36 זַגָא דְדַהֲבָא וְרִמוֹנָא זַגָא דְדַהֲבָא וְרִמוֹנָא עַל שִׁיפוֹלֵי מְעִילָא סְחוֹר סְחוֹר:
@37 וִיהֵי עַל אַהֲרֹן לְשַׁמָשָׁא וְיִשְׁתְּמַע קָלֵהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא קֳדָם יְיָ וּבְמִפְקֵהּ וְלָא יְמוּת:
@38 וְתַעְבֵּד צִיצָא דִדְהַב דְכֵי וְתִגְלוֹף עֲלוֹהִי כְּתַב מִפָרַשׁ קֹדֶשׁ לַיָי:
@39 וּתְשַׁוִי יָתֵהּ עַל חוּטָא דִתְכֶלְתָּא וִיהֵי עַל מִצְנֶפְתָּא לָקֳבֵל אַפֵּי מִצְנֶפְתָּא יְהֵי:
@40 וִיהֵי עַל בֵּית עֵינוֹהִי דְאַהֲרֹן וְיִטּוֹל אַהֲרֹן יָת עֲוָיַת קוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל לְכָל מַתְּנַּת קוּדְשֵׁיהוֹן וִיהֵי עַל בֵּית עֵינוֹהִי תְּדִירָא לְרַעֲוָא לְהוֹן קֳדָם יְיָ:
@41 וּתְרַמֵץ כִּתּוּנָא בוּצָא וְתַעְבֵּד מִצְנֶפְתָּא דְבוּצָא וְהֶמְיָנָא תַּעְבֵּד עוֹבַד צַיָר:
@42 וְלִבְנֵי אַהֲרֹן תַּעְבֵּד כִּתּוּנִין וְתַעְבֵּד לְהוֹן הֶמְיָנִין וְכוֹבָעִין תַּעְבֵּד לְהוֹן לִיקָר וּלְתֻשְׁבְּחָן:
@43 וְתַלְבֵּש יָתְהוֹן יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ וּתְרַבֵּי יָתְהוֹן וּתְקָרֵב יָת קֻרְבָּנְהוֹן וּתְקַדֵשׁ יָתְהוֹן וִישַׁמְשׁוּן קֳדָמַי:
@44 וְעִבֵד לְהוֹן מִכְנְסִין דְבוּץ לְכַסָאָה בְשַׂר עֶרְיְתָא מֵחַרְצָן וְעַד יַרְכָּן יְהוֹן:
@45 וִיהוֹן עַל אַהֲרֹן וְעַל בְּנוֹהִי בְּמֵעַלְהוֹן לְּמַשְׁכַּן זִמְנָא אוֹ בְמִקְרָבְהוֹן לְמַדְבְּחָא לְשַׁמָשָׁא בְקוּדְשָׁא וְלָא יְקַבְּלוּן חוֹבָא וִימוּתוּן קְיָם עָלָם לֵהּ וְלִבְנוֹהִי בַתְרוֹהִי:
@46 וְדֵין פִּתְגָמָא דִי תַעְבֵּד לְהוֹן לְקַדָשָׁא יָתְהוֹן לְשַׁמָשָׁא קֳדָמַי סַב תּוֹר חָד בַּר תּוֹרֵי וְדִכְרִין תְּרֵין שַׁלְמִין:
@47 וּלְחֵם פַּטִיר וּגְרִיצִין פַּטִּירִין דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִּירִין דִמְשִׁיחִין בִּמְשָׁח סֻלְתָּא חִטִין תַּעְבֵּד יָתְהוֹן:
@48 וְתִתֵּן יָתְהוֹן עַל סַלָא חַד וּתְקָרֵב יָתְהוֹן בְּסַלָא וְיָת תּוֹרָא וְיָת תְּרֵין דִכְרִין:
@49 וְיָת אַהֲרֹן וְיָת בְּנוֹהִי תְּקָרֵב לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@50 וְתִסַב יָת לְבוּשַׁיָא וְתַלְבֵּשׁ יָת אַהֲרֹן יָת כִּתּוּנָא וְיָת מְעִיל אֵפוֹדָא וְיָת אֵפוֹדָא וְיָת חוּשְׁנָא וְתַתְקֵן לֵהּ בְּהֶמְיַן אֵפוֹדָא:
@51 וּתְשַׁוִי מִצְנֶפְתָּא עַל רֵישֵׁהּ וְתִתֵּן יָת כְּלִילָא דְקוּדְשָׁא עַל מִצְנֶפְתָּא:
@52 וְתִסַב יָת מִשְׁחָא דִרְבוּתָא וּתְרִיק עַל רֵישֵׁהּ וּתְרַבֵּהּ יָתֵהּ:
@53 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשִׁנוּן כִּתּוּנִין:
@54 וּתְזָרֵז יָתְהוֹן הֶמְיָנִין אַהֲרֹן וּבְנוֹהִי וְתַתְקֵן לְהוֹן כּוֹבָעִין וּתְהֵי לְהוֹן כְּהֻנְתָּא לִקְיַם עָלָם וּתְקָרֵב קֻרְבָּנָא דְאַהֲרֹן וְקֻרְבָּנָא דִבְנוֹהִי:
@55 וּתְקָרֵב יָת תּוֹרָא לִקֳדָם מַשְׁכַּן זִמְנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא:
@56 וְתִכּוֹס יָת תּוֹרָא קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@57 וְתִסַב מִדְמָא דְתוֹרָא וְתִתֵּן עַל קַרְנַת מַדְבְּחָא בְּאֶצְבְּעָךְ וְיָת כָּל דְמָא תֵישׁוֹד לִיסוֹדָא דְמַדְבְּחָא:
@58 וְתִסַב יָת כָּל תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חִצְרָא דִעַל כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְתַסֵיק לְמַדְבְּחָא:
@59 וְיָת בִּסְרָא דְתוֹרָא וְיָת מַשְׁכֵהּ וְיָת אוּכְלֵהּ תּוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא חַטָאתָא הוּא:
@60 וְיָת דִכְרָא חַד תִּסַב וְיִסְמְכוּן אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@61 וְתִכּוֹס יָת דִכְרָא וְתִסַב יָת דְמֵהּ וְתִזְרוֹק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@62 וְיָת דִכְרָא תְּפַלֵג לְאֵבָרוֹהִי וּתְחַלִיל גַּוֵהּ וּכְרָעוֹהִי וְתִתֵּן עַל אֵבָרוֹהִי וְעַל רֵישֵׁהּ:
@63 וְתַסֵיק יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ הוּא:
@64 וְתִסַב יָת דִכְרָא תִנְיָנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@65 וְתִכּוֹס יָת דִכְרָא וְתִסַב מִדְמֵהּ וְתִתֵּן עַל רוּם אוּדְנָא דְאַהֲרֹן וְעַל רוּם אוּדְנָא דִבְנוֹהִי דְיַמִינָא וְעַל אִלְיוֹן יְדֵיהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וְתִזְרוֹק יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@66 וְתִסַב מִן דְמָא דִי עַל מַדְבְּחָא וּמִמִשְׁחָא דִרְבוּתָא וְתַדֵי עַל אַהֲרֹן וְעַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְיִתְקַדַשׁ הוּא וּלְבוּשׁוֹהִי וּבְנוֹהִי וּלְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@67 וְתִסַב מִן דִכְרָא תַּרְבָּא וְאַלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּן כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְיָת שׁוֹקָא דְיַמִינָא אֲרֵי דְכַר קֻרְבָּנָא הוּא:
@68 וּפִתָּא דִלְחֵם חַד וּגְרִצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד מִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ:
@69 וּתְשַׁוֵי כֹלָא עַל יְדָא דְאַהֲרֹן וְעַל יְדָא דִבְנוֹהִי וּתְרִים יָתְהוֹן אֲרָמוּתָא קֳדָם יְיָ:
@70 וְתִסַב יָתְהוֹן מִידֵיהוֹן וְתַסֵיק לְמַדְבְּחָא עַל עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ קֻרְבָּנָא הוּא קֳדָם יְיָ:
@71 וְתִסַב יָת חֶדְיָא מִדְכַר קֻרְבָּנַיָא דִי לְאַהֲרֹן וּתְרִים יָתֵהּ אֲרָמוּתָא קֳדָם יְיָ וִיהֵי לָךְ לָחֳלָק:
@72 וּתְקַדֵשׁ יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא דִי אִתָּרַם וְדִי אִתַּפְרָשׁ מִדְכַר קֻרְבָּנַיָא מִדִי לְאַהֲרֹן וּמִדִי לִבְנוֹהִי:
@73 וִיהֵי לְאַהֲרֹן וְלִבְנוֹהִי לִקְיַם עָלָם מִן בְּנֵי יִשְׂרָאֵל אֲרֵי אַפְרָשׁוּתָא הוּא וְאַפְרָשׁוּתָא יְהֵי מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן אַפְרָשׁוּתְהוֹן קֳדָם יְיָ:
@74 וּלְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן יְהוֹן לִבְנוֹהִי בַּתְרוֹהִי לְדַכָּאָה בְהוֹן וּלְקָרָבָא בְהוֹן יָת קֻרְבָּנְהוֹן:
@75 שִׁבְעַת יוֹמִין יַלְבֵּשִׁנוּן כַּהֲנָא תְּחוֹתוֹהִי מִבְּנוֹהִי דִי יֵעוֹל לְמַשְׁכַּן זִמְנָא לְשַׁמָשָׁא בְקוּדְשָׁא:
@76 וְיָת דְכַר קֻרְבָּנַיָא תִּסָב וּתְבַשֵׁל יָת בִּסְרֵהּ בַּאֲתַר קַדִישׁ:
@77 וְיֵכוּל אַהֲרֹן וּבְנוֹהִי יָת בְּסַר דִכְרָא וְיָת לַחְמָא דִי בְסַלָא לִתְרַע מַשְׁכַּן זִמְנָא:
@78 וְיֵכְלוּן יָתְהוֹן דִי יִתְכַּפַּר בְּהוֹן לְקָרָבָא יָת קֻרְבָּנְהוֹן לְקַדָשָׁא יָתְהוֹן וְחִלוֹנַי לָא יֵיכוּל אֲרֵי קוּדְשָׁא אִנוּן:
@79 וְאִם יִשְׁתָּאַר מִבְּסַר קֻרְבָּנַיָא וּמִן לַחְמָא עַד צַפְרָא וְתוֹקִיד יָת דְאִשְׁתָּאַר בְּנוּרָא לָא יִתְאֲכֵל אֲרֵי קוּדְשָׁא הוּא:
@80 וְתַעְבֵּד לְאַהֲרֹן וְלִבְנוֹהִי כְּדֵין כְּכֹל דִי פַקֵּדִית יָתָךְ שִׁבְעַת יוֹמִין תְּקָרֵב קֻרְבָּנְהוֹן:
@81 וְתוֹרָא דְחַטָאתָא תַּעְבֵּד לְיוֹמָא עַל כִּפּוּרַיָא וּתְדַכֵּי עַל מַדְבְּחָא בְּכַפָּרוּתָךְ עֲלוֹהִי וּתְרַבֵּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@82 שִׁבְעַת יוֹמִין תְּכַפֵּר עַל מַדְבְּחָא וּתְקַדֵשׁ יָתֵהּ וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשַׁיָא כָּל דְיִקְרַב בְּמַדְבְּחָא יִתְקַדָשׁ:
@83 וְדֵין דִי תַעְבֵּד עַל מַדְבְּחָא אִמְרִין בְּנֵי שְׁנָא תְּרֵין לְיוֹמָא תְּדִירָא:
@84 יָת אִמְרָא חַד תַּעְבֵּד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא:
@85 וְעִסְרוֹנָא סֻלְתָּא דְפִילָא בִמְשַׁח כָּתִישָׁא רַבְעוּת הִינָא וְנִסְכָּא רַבְעוּת הִינָא חַמְרָא לְאִמְרָא חָד:
@86 וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכַּהּ תַּעְבֵּד לַהּ לְאִתְקַּבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ:
@87 עֲלָתָא תְדִירָא לְדָרֵיכוֹן בִּתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ דִאֱזַמֵן מֵימְרִי לְכוֹן תַּמָן לְמַלָלָא עִמָךְ תַּמָן:
@88 וֶאֱזַמֵן מֵימְרִי תַמָן לִבְנֵי יִשְׂרָאֵל וְיִתְקַדַשׁ בִּיקָרִי:
@89 וֶאֱקַדֵשׁ יָת מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא וְיָת אַהֲרֹן וְיָת בְּנוֹהִי אֱקַדֵשׁ לְשַׁמָשָׁא קֳדָמַי:
@90 וְאַשְׁרֵי שְׁכִנְתִּי בְּגוֹ בְּנֵי יִשְׂרָאֵל וְאֶהֱוֵי לְהוֹן לֶאֱלָהּ:
@91 וְיִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְאַשְׁרָאָה שְׁכִנְתִּי בֵּינֵיהוֹן אֲנָא יְיָ אֱלָהֲהוֹן:
@92 וְתַעְבֵד מַדְבְּחָא לְאַקְטָרָא עֲלוֹהִי קְטוֹרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין תַּעְבֵּד יָתֵהּ:
@93 אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע יְהֵי וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ קַרְנוֹהִי:
@94 וְתַחֲפֵי יָתֵהּ דְהַב דְכֵי יָת אִגָרֵהּ וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וְתַעְבֵּד לֵהּ דֵיר דִדְהב סְחוֹר סְחוֹר:
@95 וְתַרְתֵּין עִזְקַן דִדְהַב תַּעְבֶּד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ תַּעְבֵּד עַל תְּרֵין סִטְרוֹהִי וִיהֵי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@96 וְתַעְבֵּד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא:
@97 וְתִתֵּן יָתֵה קֳדָם פָּרֻכְתָּא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא לִקֳדָם כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא דִי אֲזַמֵן מֵימְרִי לָךְ תַּמָן:
@98 וְיַקְטַר עֲלוֹהִי אַהֲרֹן קְטוֹרֶת בּוּסְמִין בִּצְפַר בִּצְפַר בְּאַתְקָנוּתֵהּ יָת בּוֹצִינַיָא יַסֵקִנַהּ:
@99 וּבְאַדְלָקוּת אַהֲרֹן יָת בּוֹצִינַיָא בֵּין שִׁמְשַׁיָא יַסֵקִנַהּ קְטוֹרֶת בּוּסְמַיָא תְדִירָא קֳדָם יְיָ לְדָרֵיכוֹן:
@100 לָא תַסְקוּן עֲלוֹהִי קְטוֹרֶת בּוּסְמִין נוּכְרָאִין וַעֲלָתָא וּמִנְחָתָא וְנִסְכָּא לָא תְנַסְכוּן עֲלוֹהִי:
@101 וִיכַפֵר אַהֲרֹן עַל קַרְנוֹהִי חֲדָא בְּשַׁתָּא מִדְמָא חַטַאת כִּפּוּרַיָא חֲדָא בְשַׁתָּא יְכַפֵּר עֲלוֹהִי לְדָרֵיכוֹן קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ: פפפ:

@1 **ואתה תצוה' זך.** בלי שמרים, כמו ששנינו במנחות (פו א) מגרגרו בראש הזית וכו' : **כתית.** הזיתים היה כותש במכתשת, ואינו טוחנן בריחים, כדי שלא יהו בו שמרים, ואחר שהוציא טפה ראשונה מכניסן לריחים וטוחנן, והשמן השני פסול למנורה וכשר למנחות, שנאמר כתית למאור, ולא כתית למנחות: **להעלות נר תמיד.** מדליק עד שתהא שלהבת עולה מאליה: **תמיד.** כל לילה ולילה קרוי תמיד, כמו שאתה אומר (במדבר כח ו) עולת תמיד, ואינה אלא מיום ליום. וכן במנחת חבתין נאמר (ויקרא ו יג) תמיד, ואינה אלא מחציתה בבקר ומחציתה בערב. אבל תמיד האמור בלחם הפנים משבת לשבת הוא:
@2 **מערב עד בקר.** תן לה מדתה שתהא דולקת מערב עד בקר, ושערו חכמים חצי לוג ללילי טבת הארכין, וכן לכל הלילות, ואם יותר אין בכך כלום:
@3 **ואתה הקרב אליך.** לאחר שתגמר מלאכת המשכן:
@5 **לקדשו לכהנו לי.** לקדשו להכניסו בכהנה על ידי הבגדים שיהא כהן לי, ולשון כהנה שרות הוא, שוריינטריא''ה בלעז :
@6 **חשן.** תכשיט כנגד הלב: **ואפוד.** לא שמעתי ולא מצאתי בברייתא פרוש תבניתו, ולבי אומר לי שהוא חגור לו מאחוריו, רחבו כרוחב גב איש, כמין סינר שקורין פורציינ''ט בלעז שחוגרות השרות כשרוכבות על הסוסים, כך מעשהו מלמטה, שנאמר (שמואל ב ו יד) ודוד חגור אפוד בד, למדנו שהאפוד חגורה היא. ואי אפשר לומר שאין בו אלא חגורה לבדה, שהרי נאמר (ויקרא ח ז) ויתן עליו את האפוד, ואחר כך ויחגור אותו בחשב האפוד, ותרגם אנקלוס בהמין אפודא, למדנו שהחשב הוא החגור, והאפוד שם תכשיט לבדו. ואי אפשר לומר שעל שם שתי הכתפות שבו הוא קרוי אפוד, שהרי נאמר (פסוק כז) שתי כתפות האפוד, למדנו שהאפוד שם לבד, והכתפות שם לבד, והחשב שם לבד. לכך אני אומר שעל שם הסינר של מטה קרוי אפוד, על שם שאופדו ומקשטו בו, כמו שנאמר (ויקרא ח ז) ויאפוד לו בו, והחשב הוא החגור של מעלה המנו, והכתפות קבועות בו. ועוד אומר לי לבי, שיש ראיה שהוא מין לבוש, שתרגם יונתן (שמואל ב' ו יד) ודוד חגור אפוד בד, כרדוט דבוץ. ותרגם כמו כן מעילים, כרדוטין, במעשה תמר אחות אבשלום (שמואל ב יג יח) כי כן תלבשנה בנות המלך הבתולות מעילים: **ומעיל.** הוא כמין חלוק, וכן הכתנת, אלא שהכתונת סמוך לבשרו ומעיל קרוי חלוק עליון: **תשבץ.** עשויין משבצות לנוי, והמשבצות הן כמין גמות העשויות בתכשיטי זהב למושב קביעות אבנים טובות ומרגליות, כמו שנאמר באבני האפוד (פסוק יא) מסבות משבצות זהב, ובלעז קוראין אותו קשטונ''ש : **מצנפת.** כמין כפת כובע שקורין קויפ''א בלעז , שהרי במקום אחר קורא להם (לט כח) מגבעות, ומתרגמנן קובעיא: **ואבנט.** היא חגורה על הכתנת, והאפוד חגורה על המעיל, כמו שמצינו בסדר לבישתן (ויקרא ח ז) ויתן עליו את הכתנת ויחגור אותו באבנט וילבש אותו את המעיל ויתן עליו את האפוד: **בגדי קדש.** מתרומה המקדשת לשמי יעשו אותם:
@7 **והם יקחו.** אותם חכמי לב שיעשו הבגדים, יקבלו מן המתנדבים את הזהב ואת התכלת לעשות מהן את הבגדים:
@8 **ועשו את האפוד.** אם באתי לפרש מעשה האפוד והחשן על סדר המקראות, הרי פרושן פרקים פרקים, וישגה הקורא בצרופן, לכך אני כותב מעשיהם כמות שהוא, למען ירוץ הקורא בו, ואחר כך אפרש על סדר המקראות. האפוד עשוי כמין סינר של נשים רוכבות סוסים, וחוגר אותו מאחוריו כנגד לבו למטה מאציליו, רחבו כמדת רוחב גבו של אדם ויותר ומגיע עד עקביו, והחשב מחבר בראשו על פני רחבו מעשה אורג, ומאריך לכאן ולכאן כדי להקיף ולחגור בו, והכתפות מחברות בחשב אחד לימין ואחד לשמאל, מרוחקות זו מזו שעור הבדלת כתפים, מאחורי הכהן לשני קצות רחבו של סינר, וכשזוקפן עומדות לו על שני כתפיו, והן כמין שתי רצועות עשויות ממין האפוד, ארכות כדי שעור לזקפן אצל צוארו מכאן ומכאן, ונקפלות לפניו למטה מכתפיו מעט, ואבני השהם קבועות בהם, אחת על כתף ימין ואחת על כתף שמאל, והמשבצות נתונות בראשיהם לפני כתפיו, ושתי עבותות הזהב תחובות בשתי טבעות שבחשן בשני קצות רחבו העליון, אחת לימין ואחת לשמאל, ושני ראשי השרשרת [הימנית] תקועין במשבצות לימין, וכן שני ראשי השרשרת השמאלית תקועין במשבצות שבכתף שמאל, נמצא החושן תלוי במשבצות האפוד על לבו מלפניו. ועוד שתי טבעות בשני קצות החשן בתחתיתו וכנגדם שתי טבעות בשתי כתפות האפוד מלמטה בראשו התחתון המחבר בחשב, טבעות החשן אל מול טבעות האפוד שוכבים זה על זה ומרכסן בפתיל תכלת תחוב בטבעות האפוד והחשן, שיהא תחתית החשן דבוק לחשב האפוד ולא יהא נד ונבדל, הולך וחוזר: **זהב תכלת וארגמן תולעת שני ושש משזר.** חמשת מינים הללו שזורין בכל חוט וחוט היו מרדדין את הזהב כמין טסין דקין וקוצצין פתילים מהם, וטווין אותן חוט של זהב עם ששה חוטים של תכלת, וחוט של זהב עם ששה חוטין של ארגמן, וכן בתולעת שני, וכן בשש, שכל המינין חוטן כפול ששה, וחוט של זהב עם כל אחד ואחד, ואחר כך שוזר את כלם כאחד, נמצא חוטן כפול עשרים ושמונה. וכן מפורש במסכת יומא (עב א) , ולמד מן המקרא הזה (שמות לט ג) וירקעו את פחי הזהב וקצץ פתילים לעשות, את פתילי הזהב, בתוך התכלת ובתוך הארגמן וגו' , למדנו שחוט של זהב שזור עם כל מין ומין: **מעשה חשב.** כבר פרשתי (שמות כו א) שהוא אריגת שתי קירות שאין צורות שני עבריה דומות זו לזו:
@9 **שתי כתפות** וגו' **.** הסינר מלמטה, וחשב האפוד היא החגורה וצמודה לו מלמעלה דגמת סינר הנשים, ומגבו של כהן היו מחברות בחשב. שתי חתכות כמין שתי רצועות רחבות, אחת כנגד כל כתף וכתף, וזוקפן על שתי כתפותיו עד שנקפלות לפניו כנגד החזה, ועל ידי חבורן לטבעות החשן נאחזין מלפניו כנגד לבו שאין נופלות, כמו שמפורש בענין, והיו זקופות והולכות כנגד כתפיו, ושתי אבני השהם קבועות בהן, אחת בכל אחת: **אל שני קצותיו.** אל רחבו של אפוד, שלא היה רחבו אלא כנגד גבו של כהן, וגבהו עד כנגד האצילים שקורין קודי''ש בלעז [מרפקים] שנאמר (יחזקאל מד יח) לא יחגרו ביזע, אין חוגרין במקום זיעה, לא למעלה מאציליהם ולא למטה ממתניהם, אלא כנגד אציליהם: **וחבר.** האפוד עם אותן שתי כתפות האפוד, יחבר אותם במחט למטה בחשב, ולא יארגם עמו, אלא אורגם לבדם ואחר כך מחברם:
@10 **וחשב אפדתו.** וחגור שעל ידו הוא מאפדו ומתקנהו לכהן ומקשטו: **אשר עליו.** למעלה בשפת הסינר, היא החגורה: **כמעשהו.** כאריגת הסינר מעשה חושב ומחמשת מינים, כך אריגת החשב מעשה חושב ומחמשת מינין: **ממנו יהיה.** עמו יהיה ארוג, ולא יארגנו לבד ויחברנו:
@12 **כתולדתם.** כסדר שנלדו ראובן שמעון לוי יהודה דן נפתלי, על האחת, ועל השניה גד אשר יששכר זבולן יוסף בנימין מלא, שכן הוא כתוב במקום תולדתו, עשרים וחמש אותיות בכל אחת ואחת:
@13 **מעשה חרש אבן.** מעשה אמן של אבנים. חרש זה דבוק הוא לתבה שלאחריו, ולפיכך הוא נקוד פתח בסופו, וכן (ישעיה מד יג) חרש עצים נטה קו, חרש של עצים. וכן (ישעיה מד יב) חרש ברזל מעצד, כל אלה דבוקים ופתוחים: **פתוחי חתם.** כתרגומו כתב מפרש כגלף דעזקא, חרוצות האותיות בתוכן, כמו שחורצין חותמי טבעות שהם לחתום אגרות, כתב נכר ומפרש: **על שמות.** כמו בשמות: **מסבת משבצות.** מוקפות האבנים במשבצות זהב, שעושה מושב האבן בזהב כמין גומא למדת האבן ומשקיעה במשבצות, נמצאת המשבצת סובבת את האבן סביב, ומחבר המשבצות בכתפות האפוד:
@14 **לזכרון.** שיראה הקדוש ברוך הוא השבטים כתובים לפניו ויזכור צדקתם:
@15 **ועשית משבצות.** מעוט משבצות שתים, ולא פרש לך עתה בפרשה זו אלא מקצת צרכן, ובפרשת החושן גומר לך פרושן:
@16 **שרשרת זהב.** שלשלאות: **מגבלות.** לסוף גבול החשן תעשה אותם: **מעשה עבות.** מעשה קליעת חוטין, ולא מעשה נקבים וכפלים, כאותן שעושין לבורות, אלא כאותן שעושין לערדסקאות, שקורין אינצינשייר''ש בלעז [כלי קטורת] : **ונתת את שרשרת.** של עבותות העשויות מעשה עבות על המשבצות הללו. ולא זה הוא מקום צואת עשיתן של שרשרות, ולא צואת קביעתן, ואין תעשה האמור כאן לשון צווי, ואין ונתתה האמור כאן לשון צווי, אלא לשון עתיד, כי בפרשת החשן חוזר ומצוה על עשיתן ועל קביעתן, ולא נכתב כאן אלא להודיע מקצת צורך המשבצות שצוה לעשות עם האפוד, וכתב לך זאת לומר לך המשבצות הללו יזקקו לך לכשתעשה שרשרות מגבלות על החשן, תתנם על המשבצות הללו:
@17 **חשן משפט.** שמכפר על קלקול הדין. דבר אחר משפט, שמברר דבריו והבטחתו אמת, דיריישנימינ''ט בלעז . שהמשפט משמש שלש לשונות דברי טענות הבעלי דינים, וגמר הדין, ועונש הדין, אם עונש מיתה, אם עונש מכות, אם עונש ממון, וזה משמש לשון ברור דברים, שמפרש ומברר דבריו: **כמעשה אפוד.** מעשה חושב ומחמשת מינין:
@18 **זרת ארכו וזרת רחבו.** כפול ומוטל לו לפניו כנגד לבו, שנאמר (פסוק ל) והיו על לב אהרן, תלוי בכתפות האפוד, הבאות מאחוריו על כתפיו ונקפלות ויורדות לפניו מעט, והחשן תלוי בהן בשרשרות וטבעות, כמו שמפורש בענין:
@19 **ומלאת בו.** על שם שהאבנים ממלאות גמות המשבצות המתקנות להן, קורא אותן בלשון מלאים:
@22 **משבצים זהב.** יהיו הטורים במלואתם, מקפים משבצות זהב בעומק שעור שיתמלא בעובי האבן, זהו לשון במלואתם, כשיעור מלוי עביין של אבנים יהיה עומק המשבצות לא פחות ולא יותר:
@23 **איש על שמו.** כסדר תולדותם סדר האבנים, אודם לראובן, פטדה לשמעון, וכן כלם:
@24 **על החשן.** בשביל החשן, לקבעם בטבעותיו, כמו שמפורש למטה בענין: **שרשת.** לשון שרשי אילן המאחיזין לאילן להאחז ולהתקע בארץ, אף אלו יהיו מאחיזין לחשן, שבהם יהיה תלוי באפוד, והן שתי שרשרות האמורות למעלה (פסוק יד) בענין המשבצות. ואף שרשרות פתר מנחם בן סרוק לשון שרשים, ואמר שהרי''ש יתרה, כמו מ''ם שבשלשום, ומ''ם שבריקם. ואיני רואה את דבריו, אלא שרשרת בלשון עברית, כשלשלת בלשון משנה: **גבלת.** הוא מגבלות האמור למעלה (פסוק יד) שתתקעם בטבעות, שיהיו בגבול החשן, וכל גבול לשון קצה, אשומיי''ל בלעז : **מעשה עבות.** מעשה קליעה:
@25 **על החשן.** לצורך החושן, כדי לקבעם בו. ולא יתכן לומר שתהא תחלת עשיתן עליו, שאם כן מה הוא שחוזר ואומר ונתת את שתי הטבעות, והלא כבר נתונים בו, היה לו לכתוב בתחלת המקרא ועשית על קצות החשן שתי טבעות זהב, ואף בשרשרות צריך אתה לפתור כן: **על שני קצות החשן.** לשתי פאות שכנגד הצואר, לימנית ולשמאלית הבאים מול כתפות האפוד:
@26 **ונתתה את שתי עבתת הזהב.** הן הן שרשרות גבלות הכתובות למעלה (פסוק כב) ולא פרש מקום קבוען בחשן, עכשיו מפרש לך שיהא תוחב אותן בטבעות, ותדע לך שהן הן הראשונות, שהרי בפרשת אלה פקודי לא הכפלו:
@27 **ואת שתי קצות.** של שתי העבותות שני ראשיהם שלכל אחת: **תתן על שתי המשבצות.** הן הכתובות למעלה (פסוק יד) בין פרשת החשן ופרשת האפוד, ולא פרש את צרכן ואת מקומן, עכשיו מפרש שיתקע בהן ראשי העבותות התחובות בטבעות [בראשי] החשן לימין ולשמאל אצל הצואר, שני ראשי השרשרת הימנית תוקע במשבצות של ימין, וכן בשל שמאל שני ראשי שרשרות השמאלית: **ונתתה.** המשבצות: **על כתפות האפוד.** אחת בזו ואחת בזו, נמצאו כתפות האפוד מחזיקין את החשן שלא יפל, ובהן הוא תלוי, ועדין שפת החשן התחתונה הולכת ובאה ונוקשת על כרסו, ואינה דבוקה לו יפה, לכך הצרך עוד שתי טבעות לתחתיתו, כמו שמפרש והולך: **אל מול פניו.** של אפוד, שלא יתן המשבצות בעבר הכתפות שכלפי המעיל, אלא בעבר העליון שכלפי החוץ, והוא קרוי מול פניו של אפוד, כי אותו עבר שאינו נראה אינו קרוי פנים:
@28 **על שני קצות החשן.** הן שתי פאותיו התחתונות לימין ולשמאל: **על שפתו אשר אל עבר האפד ביתה.** הרי לך שני סימנין האחד שיתנם בשני קצות של תחתיתו שהוא כנגד האפוד, שעליונו אינו כנגד האפוד, שהרי סמוך לצואר הוא, והאפוד נתון על מתניו, ועוד נתן סימן שלא יקבעם בעבר החשן שכלפי החוץ, אלא בעבר שכלפי פנים שנאמר ביתה, ואותו העבר הוא לצד האפוד, שחשב האפוד חוגרו הכהן ונקפל הסינר לפני הכהן על מתניו, וקצת כרסו מכאן ומכאן עד כנגד קצות החשן, וקצותיו שוכבין עליו:
@29 **על שתי כתפות האפוד מלמטה.** שהמשבצות נתונות בראשי כתפות האפוד העליונים הבאים על כתפיו כנגד גרונו, ונקפלות ויורדות לפניו, והטבעות צוה לתן בראשן השני, שהוא מחבר לאפוד, והוא שנאמר לעמת מחברתו, סמוך למקום חבורן באפוד למעלה מן החגורה מעט, שהמחברת לעמת החגורה, ואלו נתונים מעט בגובה זקיפת הכתפות, הוא שנאמר ממעל לחשב האפוד, והן כנגד סוף החשן, ונותן פתיל תכלת באותן הטבעות ובטבעות החשן, ורוכסן באותן פתילין לימין ולשמאל, שלא יהא תחתית החושן הולך לפנים וחוזר לאחור ונוקש על כרסו, ונמצא מישב על המעיל יפה: **ממול פניו.** בעבר החיצון:
@30 **וירכסו.** לשון חבור, וכן (תהלים לא כא) מרכסי איש, חבורי חבלי רשעים, וכן (ישעיה מ ד) והרכסים לבקעה, הרים הסמוכים זה לזה שאי אפשר לירד לגיא שביניהם אלא בקושי גדול, שמתוך סמיכתן הגיא זקופה ועמוקה, יהיו לבקעת מישור ונוחה לילך: **להיות על חשב האפוד.** להיות החשן דבוק אל חשב האפוד: **ולא יזח.** לשון נתוק, ולשון ערבי הוא, כדברי דונש בן לברט:
@32 **את האורים ואת התמים.** הוא כתב שם המפורש, שהיה נותנו בתוך כפלי החשן, שעל ידו הוא מאיר דבריו ומתמם את דבריו. ובמקדש שני היה החשן, שאי אפשר לכהן גדול להיות מחסר בגדים, אבל אותו השם לא היה בתוכו, ועל שם אותו הכתב הוא קרוי משפט, שנאמר (במדבר כז כא) ושאל לו במשפט האורים: **את משפט בני ישראל.** דבר שהם נשפטים ונוכחים על ידו אם לעשות דבר או לא לעשות. ולפי מדרש אגדה שהחשן מכפר על מעותי הדין, נקרא משפט על שם סליחת המשפט:
@33 **את מעיל האפוד.** שהאפוד נתון עליו לחגורה: **כליל תכלת.** כלו תכלת, שאין מין אחר מעורב בו:
@34 **והיה פי ראשו.** פי המעיל שבגבהו הוא פתיחת בית הצואר: **בתוכו.** כתרגומו כפיל לגויה, כפול לתוכו להיות לו לשפה כפילתו, והיה מעשה אורג ולא במחט: **כפי תחרא.** למדנו שהשריונים שלהם פיהם כפול לתוכן: **לא יקרע.** כדי שלא יקרע, והקורעו עובר בלאו, שזה ממנין לאוין שבתורה, וכן (פסוק כח) ולא יזח החשן, וכן (שמות כה טו) לא יסורו ממנו. הנאמר בבדי הארון:
@35 **רמוני.** עגולים וחלולים היו כמין רמונים העשויים כביצת תרנגולת: **ופעמוני זהב.** זגין עם ענבלין שבתוכם: **בתוכם סביב.** ביניהם סביב, בין שני רמונים פעמון אחד דבוק ותלוי בשולי המעיל:
@36 **פעמון זהב ורמון פעמון זהב ורמון.** אצלו:
@37 **ולא ימות.** מכלל לאו אתה שומע הן, אם יהיו לו לא יתחיב מיתה, הא אם יכנס מחסר אחד מן הבגדים הללו חיב מיתה בידי שמים:
@38 **ציץ.** כמין טס של זהב היה, רוחב שתי אצבעות, מקיף על המצח מאוזן לאוזן:
@39 **על פתיל תכלת.** ובמקום אחר הוא אומר (שמות לט לא) ויתנו עליו פתיל תכלת, ועוד כתיב כאן והיה על המצנפת, ולמטה הוא אומר (פסוק לח) והיה על מצח אהרן, ובשחיטת קדשים שנינו (זבחים יט א) שערו היה נראה בין ציץ למצנפת, ששם מניח תפלין, למדנו שהמצנפת למעלה בגובה הראש ואינה עמוקה לכנס בה כל הראש עד המצח, והציץ מלמטה, והפתילים היו בנקבים ותלויין בו בשני ראשים ובאמצעיתו ששה בשלושה מקומות הללו, פתיל מלמעלה, אחד מבחוץ, ואחד מבפנים כנגדו, וקושר ראשי הפתילים מאחורי העורף שלשתן, ונמצאו בין אורך הטס ופתילי ראשו מקיפין את הקדקד, ופתיל האמצעי שבראשו קשור עם ראשי השנים, הולך על פני רוחב הראש מלמעלה, ונמצא עשוי כמין כובע, ועל פתיל האמצעי הוא אומר והיה על המצנפת, והיה נותן הציץ על ראשו כמין כובע על המצנפת, והפתיל האמצעי מחזיקו שאינו נופל, והטס תלוי כנגד מצחו, ונתקימו כל המקראות פתיל על הציץ, וציץ על הפתיל, והפתיל על המצנפת מלמעלה:
@40 **ונשא אהרן.** לשון סליחה, ואף על פי כן אינו זז ממשמעו, אהרן נושא את המשא שלעון, נמצא מסלק העון מן הקדשים: **את עון הקדשים.** לרצות על הדם ועל החלב שקרבו בטומאה, כמו ששנינו (פסחים טז א) אי זה עון הוא נושא, אם עון פגול, הרי כבר נאמר (ויקרא יט ז) לא ירצה, ואם עון נותר, הרי נאמר (ויקרא ז יח) לא יחשב, ואין לומר שיכפר על עון הכהן שהקריב טמא, שהרי עון הקדשים נאמר, ולא עון המקריבים, הא אינו מרצה אלא להכשיר הקרבן: **והיה על מצחו תמיד.** אי אפשר לומר שיהא על מצחו תמיד, שהרי אינו עליו אלא בשעת העבודה, אלא תמיד לרצות להם, אפלו אינו על מצחו, שלא היה כהן גדול עובד באותה שעה. ולדברי האומר (יומא ז ב) עודהו על מצחו מכפר ומרצה, ואם לאו אינו מרצה, נדרש על מצחו תמיד, מלמד שמשמש בו בעודו על מצחו, שלא יסיח דעתו ממנו:
@41 **ושבצת.** עשה אותה משבצות משבצות, וכלה של שש:
@42 **ולבני אהרן תעשה כתנת.** ארבעה בגדים הללו ולא יותר כתנת, ואבנט, ומגבעות היא מצנפת, ומכנסים הכתובים למטה בפרשה (פסוק מב) :
@43 **והלבשת אתם את אהרן.** אותם האמורים באהרן חשן ואפוד ומעיל וכתונת תשבץ, מצנפת ואבנט וציץ ומכנסים, הכתובים למטה בכלם: **ואת בניו אתו.** אותם הכתובים בהם: **ומשחת אותם.** את אהרן ואת בניו בשמן המשחה: **ומלאת את ידם.** כל מלוי ידים לשון חנוך, כשהוא נכנס לדבר להיות מחזק בו מאותו יום והלאה הוא מלוי, ובלשון לעז כשממנין אדם על פקידת דבר, נותן השליט בידו בית יד של עור שקורין גנ''ט בלעז [כפפה] , ועל ידו הוא מחזיקו בדבר, וקורין לאותו מסירה ריוישטי''ר בלעז [להסמיך] והוא מלוי ידים:
@44 **ועשה להם.** לאהרן ולבניו: **מכנסי בד.** הרי שמונה בגדים לכהן גדול, וארבעה לכהן הדיוט:
@45 **והיו על אהרן.** כל הבגדים האלה על אהרן הראויין לו: **ועל בניו.** האמורים בהם: **בבאם אל אהל מועד.** להיכל, וכן למשכן: **ומתו.** הא למדת, שהמשמש מחסר בגדים במיתה: **חקת עולם לו.** כל מקום שנאמר חקת עולם, הוא גזרה מיד ולדורות, לעכב בו:
@46 **לקח.** כמו קח, ושתי גזרות הן, אחת של קיחה, ואחת של לקיחה, ולהן פתרון אחד: **פר אחד.** לכפר על מעשה העגל שהוא פר:
@47 **ולחם מצות וחלת מצת ורקיקי מצות.** הרי אלו שלשה מינין רבוכה, וחלות ורקיקים לחם מצות, היא הקרויה למטה בענין (פסוק כג) חלת לחם שמן, על שם שנותן שמן ברבוכה כנגד החלות והרקיקין, וכל המינין באים עשר עשר חלות: **בלולת בשמן.** כשהן קמח יוצק בהן שמן ובוללן: **משחים בשמן.** אחר אפייתן מושחן כמין כי יונית, שהיא עשויה כנו''ן שלנו:
@48 **והקרבת אתם.** אל חצר המשכן ביום הקמתו:
@49 **ורחצת.** זו טבילת כל הגוף:
@50 **ואפדת.** קשט ותקן החגורה והסינר סביבותיו:
@51 **נזר הקדש.** זה הציץ: **על המצנפת.** כמו שפרשתי למעלה (שמות כח לז) על ידי הפתיל האמצעי ושני פתילין שבראשו הקשורין שלשתן מאחורי העורף, הוא נותנו על המצנפת כמין כובע:
@52 **ומשחת אותו.** אף משיחה זו כמין כי יונית, נותן שמן על ראשו ובין ריסי עיניו ומחברן באצבעו:
@54 **והיתה להם.** מלוי ידים זה לכהנת עולם: **ומלאת.** על ידי הדברים האלה: **יד אהרן ויד בניו.** במלוי ופקדת הכהונה:
@56 **פתח אהל מועד.** בחצר המשכן שלפני הפתח:
@57 **על קרנות.** למעלה בקרנות ממש: **ואת כל הדם.** שירי הדם: **אל יסוד המזבח.** כמין בליטת בית קבול עשוי לו סביב סביב לאחר שעלה אמה מן הארץ:
@58 **החלב המכסה את הקרב.** הוא הקרום שעל הכרס שקורין טייל''א : **ואת היתרת.** הוא טרפשא דכבדא שקורין איבדי''ש [סרעפת] : **על הכבד.** אף מן הכבד יטול עמה:
@59 **תשרף באש.** לא מצינו חטאת חיצונה נשרפת אלא זו:
@61 **וזרקת.** בכלי, אוחז במזרק וזורק כנגד הקרן כדי שיראה לכאן ולכאן, ואין קרבן טעון מתנה באצבע אלא חטאת בלבד, אבל שאר זבחים אינן טעונין קרן ולא אצבע, שמתן דמם מחצי המזבח ולמטה, ואינו עולה בכבש אלא עומד בארץ וזורק: **סביב.** כך מפורש בשחיטת קדשים (זבחים נב ב) שאין סביב אלא שתי מתנות שהן ארבע, האחת בקרן זוית זו, והאחת בקרן שכנגדה באלכסון, וכל מתנה נראית בשני צדי הקרן אלך ואלך, נמצא הדם נתן בארבע רוחות סביב, לכך קרוי סביב:
@62 **על נתחיו.** עם נתחיו, מוסף על שאר הנתחים:
@63 **ריח ניחוח.** נחת רוח לפני, שאמרתי ונעשה רצוני: **אשה.** לשון אש, והיא הקטרת איברים שעל האש:
@65 **תנוך.** הוא הסחוס האמצעי שבתוך האזן שקורין טנדרו''ם : **בהן ידם.** הגדל ובפרק האמצעי:
@67 **החלב.** זה חלב הדקים או הקיבה: **והאליה.** מן הכליות ולמטה, כמו שמפורש בויקרא (ג ט) שנאמר לעמת העצה יסירנה, מקום שהכליות יועצות, ובאמורי הפר לא נאמר אליה, שאין אליה קריבה אלא בכבש וכבשה ואיל, אבל שור ועז אין טעונים אליה: **ואת שוק הימין.** לא מצינו הקטרה בשוק הימין עם האמורים אלא זו בלבד: **כי איל מלאים הוא.** שלמים, לשון שלמות שמשלם בכל. מגיד הכתוב שהמלואים שלמים, שמשימים שלום למזבח ולעובד העבודה ולבעלים, לכך אני מצריכו החזה להיות לו לעובד העבודה למנה, וזהו משה ששמש במלואים, והשאר אכלו אהרן ובניו שהם בעלים, כמפורש בענין:
@68 **וככר לחם.** מן החלות: **וחלת לחם שמן.** ממין הרבוכה: **ורקיק.** מן הרקיקין, אחד מעשרה שבכל מין ומין ולא מצינו תרומת לחם הבא עם זבח נקטרת אלא זו בלבד, שתרומת לחמי תודה ואיל נזיר נתונה לכהנים עם חזה ושוק, ומזה לא היה למשה למנה אלא חזה בלבד:
@69 **על כפי אהרן** וגו' **והנפת.** שניהם עסוקים בתנופה, הבעלים והכהן. הא כיצד, כהן מניח ידו תחת יד הבעלים ומניף, ובזה היו אהרן ובניו בעלים, ומשה כהן: **תנופה.** מוליך ומביא למי שארבע רוחות העולם שלו, ותנופה מעכבת רוחות רעות. תרומה מעלה ומוריד למי שהשמים וארץ שלו, ומעכבת טללים רעים:
@70 **על העולה.** על האיל הראשון שהעלית עולה: **לריח ניחוח.** לנחת רוח למי שאמר ונעשה רצונו: **אשה.** לאש נתן: **לה'.** לשמו של מקום:
@72 **וקדשת את חזה התנופה ואת שוק התרומה** וגו' **.** קדשם לדורות, להיות נוהגת תרומתם והנפתם כחזה ושוק של שלמים, אבל לא להקטרה, אלא והיה לאהרן ולבניו לאכול: **תנופה.** לשון הולכה והבאה, וינטילי''ר בלעז : **הורם.** לשון מעלה ומוריד:
@73 **לחק עולם מאת בני ישראל.** שהשלמים לבעלים, ואת החזה ואת השוק יתנו לכהן: **כי תרומה הוא.** החזה ושוק הזה:
@74 **לבניו אחריו.** למי שבא בגדלה אחריו: **למשחה.** להתגדל בהם, שיש משיחה שהיא לשון שררה, כמו (במדבר יח ח) לך נתתים למשחה, (תהלים קה טו) אל תגעו במשיחי: **ולמלא בם את ידם.** על ידי הבגדים הוא מתלבש בכהנה גדולה:
@75 **שבעת ימים.** רצופין: **ילבשם הכהן.** אשר יקום מבניו תחתיו לכהנה גדולה, כשימנוהו להיות כהן גדול: **אשר יבא אל אהל מועד.** אותו כהן המוכן לכנס לפני ולפנים ביום הכפורים, וזהו כהן גדול, שאין עבודת יום הכפורים כשרה אלא בו: **תחתיו מבניו.** מלמד שאם יש לו לכהן גדול בן ממלא את מקומו, ימנוהו כהן גדול תחתיו: **הכהן תחתיו מבניו.** מכאן ראיה כל לשון כהן לשון פועל עובד ממש, לפיכך נגון תביר נמשך לפניו:
@76 **במקום קדוש.** בחצר אהל מועד, שהשלמים הללו קדשי קדשים היו:
@77 **פתח אהל מועד.** כל החצר קרוי כן:
@78 **ואכלו אתם.** אהרן ובניו, לפי שהם בעליהם: **אשר כפר בהם.** כל זרות ותיעוב: **למלא את ידם.** באיל ולחם הללו: **לקדש אתם.** שעל ידי המלאים הללו נתמלאו ידיהם ונתקדשו לכהנה: **כי קדש הם.** קדשי קדשים, ומכאן למדנו אזהרה לזר האוכל קדש קדשים, שנתן המקרא טעם לדבר משום דקדש הם:
@80 **ועשית לאהרן ולבניו ככה.** שנה הכתוב וכפל לעכב, שאם חסר דבר אחד מכל האמור בענין, לא נתמלאו ידיהם להיות כהנים ועבודתם פסולה: **אתכה.** כמו אותך: **שבעת ימים תמלא** וגו' **.** בענין הזה ובקרבנות הללו בכל יום:
@81 **על הכפרים.** בשביל הכפורים, לכפר על המזבח מכל זרות ותיעוב. ולפי שנאמר (פסוק לה) שבעת ימים תמלא ידם, אין לי אלא דבר הבא בשבילם, כגון האילים והלחם, אבל הבא בשביל המזבח, כגון פר שהוא לחטוי המזבח, לא שמענו, לכך הצרך מקרא זה. ומדרש תורת כהנים אומר כפרת המזבח הצרך, שמא התנדב איש דבר גזל במלאכת המשכן והמזבח: **וחטאת.** ותדכי, לשון מתנת דמים הנתונים באצבע קרוי חטוי: **ומשחת אתו.** בשמן המשחה וכל המשיחות כמין כי יונית:
@82 **והיה המזבח קדש.** ומה היא קדשתו, כל הנגע במזבח יקדש, אפלו קרבן פסול שעלה עליו, קדשו המזבח להכשירו שלא ירד. מתוך שנאמר כל הנגע במזבח יקדש, שומע אני בין ראוי בין שאינו ראוי, כגון דבר שלא היה פסולו בקדש, כגון הרובע והנרבע ומקצה ונעבד והטרפה וכיוצא בהן, תלמוד לומר וזה אשר תעשה, הסמוך אחריו, מה עולה ראויה אף כל ראוי, שנראה לו כבר ונפסל משבא לעזרה, כגון הלן והיוצא והטמא ושנשחט במחשבת חוץ לזמנו וחוץ למקומו וכיוצא בהן:
@85 **ועשרון סולת.** עשירית האיפה, ארבעים ושלש ביצים וחמש ביצה: **בשמן כתית.** לא לחובה נאמר כתית אלא להכשיר, לפי שנאמר (לעיל כז כ) כתית למאור, ומשמע למאור ולא למנחות, יכול לפסלו למנחות, תלמוד לומר כאן כתית, ולא נאמר (שמות כז כ) כתית למאור אלא למעט מנחות שאין צריך כתית, שאף הטחון בריחים כשר בהן: **רבע ההין.** שלשה לוגין: **ונסך.** לספלים, כמו ששנינו במסכת סכה (מח א) שני ספלים של כסף היו בראש המזבח, ומנקבים כמין שני חטמין דקים, נותן היין לתוכו והוא מקלח ויוצא דרך החוטם ונופל על גג המזבח, ומשם יורד לשיתין במזבח בית עולמים, ובמזבח הנחשת יורד מן המזבח לארץ:
@86 **לריח ניחח.** על המנחה נאמר, שמנחת נסכים כלה כליל, וסדר הקרבתן האיברים בתחלה ואחר כך המנחה, שנאמר (ויקרא כג לז) עולה ומנחה:
@87 **תמיד.** מיום אל יום, ולא יפסיק יום בנתים: **אשר אועד לכם.** כשאקבע מועד לדבר אליך שם אקבענו לבא. ויש מרבותינו למדים מכאן, שמעל מזבח הנחשת היה הקדוש ברוך הוא מדבר עם משה משהוקם המשכן, ויש אומרים מעל הכפרת, כמו שנאמר (שמות כה כב) ודברתי אתך מעל הכפורת, ואשר אועד לכם האמור כאן אינו אמור על המזבח, אלא על אהל מועד הנזכר במקרא:
@88 **ונועדתי שמה.** אתועד עמם בדבור, כמלך הקובע מקום מועד לדבר עם עבדיו שם: **ונקדש.** המשכן: **בכבודי.** שתשרה שכינתי בו. ומדרש אגדה אל תקרי בכבודי, אלא [במכבדי] , במכבדים שלי, כאן רמז לו מיתת בני אהרן ביום הקמתו, וזהו שאמר משה (ויקרא י ג) הוא אשר דבר ה' לאמר בקרובי אקדש, והיכן דבר, ונקדש בכבודי:
@91 **לשכני בתוכם.** על מנת לשכון אני בתוכם:
@92 **מקטר קטרת.** להעלות עליו קיטור עשן סמים:
@94 **את גגו.** זה היה לו גג, אבל מזבח העולה לא היה לו גג, אלא ממלאים חללו אדמה בכל חניתן: **זר זהב.** סימן הוא לכתר כהנה:
@95 **צלעותיו.** כאן הוא לשון זויות, כתרגומו, לפי שנאמר על שני צדיו, על שתי זויותיו שבשני צדיו: **והיה.** מעשה הטבעות האלה: **לבתים לבדים.** לכל בית תהיה הטבעת לבד:
@97 **לפני הפרכת.** שמא תאמר משוך מכנגד הארון לצפון או לדרום, תלמוד לומר לפני הכפרת, מכון כנגד הארון מבחוץ:
@98 **בהיטיבו.** לשון נקוי הבזכין של מנורה מדשן הפתילות שנשרפו בלילה, והיה מטיבן בכל בקר ובקר: **הנרות.** לוצי''ש בלעז [מנורות] וכן כל נרות האמורות במנורה, חוץ ממקום שנאמר שם העלאה, שהוא לשון הדלקה:
@99 **ובהעלות.** כשידליקם להעלות להבתן: **יקטירנה.** בכל יום פרס מקטיר שחרית ופרס מקטיר בין הערבים:
@100 **לא תעלו עליו.** על מזבח זה: **קטרת זרה.** שום קטורת של נדבה. כלן זרות לו חוץ מזו: **ועולה ומנחה.** ולא עולה ומנחה, עולה של בהמה ועוף, ומנחה היא של מין לחם:
@101 **וכפר אהרן.** מתן דמים: **אחת בשנה.** ביום הכפורים, הוא שנאמר באחרי מות (ויקרא טז יח) ויצא אל המזבח אשר לפני ה' וכפר עליו: **חטאת הכפורים.** הם פר ושעיר של יום הכפורים המכפרים על טומאת מקדש וקדשיו: **קדש קדשים.** המזבח מקדש לדברים הללו בלבד ולא לעבודה אחרת:

@1 אמר הכתוב בכאן **ואתה תצוה** . בעבור שאמר במשכן תמיד ועשית, והוא בצווי, אמר בכאן ואתה בעצמך תצוה להם שיקחו אליך את שמן המאור, כי אין להם דרך לעשות אותו במדבר רק אם היה אצלם משמרת. והנשיאים הביאוהו (להלן לה כז~כח):
@1 וטעם **אליך** . שיביאוהו לפניו והוא יראנו אם הוא זך וכתית כראוי, וכן צו את בני ישראל ויקחו אליך (ויקרא כד ב):
@1 וטעם **מאת בני ישראל** . שיקחו אליך השמן מאת בני ישראל מאת אשר ימצא בידם, כמו שאמר מאת כל איש אשר ידבנו לבו (לעיל כה ב). וכן אמר ואתה הקרב אליך את אהרן אחיך (להלן כח א), כי אתה בעצמך תקראם ותבשרם במעלה הזאת, ועשית להם בגדי קדש (לעיל כח ב), בצווי לחכמים העושים במלאכה, כדרך כל מלאכת התבנית. וכן ואתה תדבר אל כל חכמי לב (שם ג), שידבר עמהם הוא עצמו כי הוא יכיר את חכמתם וידע המלאכה הראויה להמסר לכל אחד מהם. ובעבור שאמר ואתה הקרב ועשית, הוצרך לפרש (בפסוק ג) ואתה תדבר אל כל חכמי לב, כי בצווי יעשו הבגדים כשאר המלאכה אשר יאמר בה ראה קראתי בשם בצלאל וגו' (להלן לא ב):
@1 **להעלות נר תמיד** . כל לילה ולילה קרוי תמיד, כמו שאתה אומר עולת תמיד (במדבר כח ו), ואינה אלא מיום ליום, וכן במנחת חביתים נאמר תמיד (ויקרא ו יג), ואינה אלא מחציתה בבקר ומחציתה בערב. אבל תמיד האמור בלחם הפנים (לעיל כה ל) הוא משבת לשבת. לשון רש''י. ומדרש רבותינו אינו כך, אלא כך שנו בספרי (ריש בהעלותך) יאירו שבעת הנרות (במדבר ח ב), שומע אני שיהיו דולקין לעולם, ת''ל מערב עד בקר (ויקרא כד ג). אי מערב עד בקר, יכול יהיו דולקים מערב עד בקר ויכבם, ת''ל יאירו שבעת הנרות. הא כיצד, יאירו שבעת הנרות מערב עד בקר. לפני ה' תמיד (שם), שיהא נר מערבי דולק תדיר, שממנו מדליקין את המנורה בין הערבים. ובתורת כהנים (שם כד ב) נמי אמרו כך להעלות נר תמיד, שיהא נר מערבי תדיר. וקתני התם, מצאו שכבה מדשנו ומדליקו ממזבח העולה, דאפילו ביום נמי מדליק נר מערבי לפי שהוא תמיד לעולם:
@1 **ובמסכת** תמיד (ג ט) שנינו כך מי שזכה בדישון המנורה נכנס ומצא שתי נרות מזרחיים דולקין מדשן את השאר ומניח את אלו דולקין במקומן. מצאן שכבו מדשנן ומדליקן מן הדולקין ואחר כך מדשן את השאר. וסתם משנה זו שנויה כדברי רבי (מנחות צח:) שאמר בנרות מזרח ומערב היו מונחין, ולדעתו נר מערבי הוא השני, ונקרא מערבי לפי שהוא מערבי לראשון, ולפי שהוא צריך להדליק נר מערבי לקיים בו לפני ה' תמיד צריך להדליק המזרחי, שאין השני נקרא מערבי עד שיהא זה מזרחי אצלו. אבל לדברי האומר (שם) צפון ודרום היו מונחין, נר מערבי הוא האמצעי שבגופה של מנורה, והוא לבדו מדליק בבקר. ועל הכלל, לפני ה' תמיד בנר מערבי, שהוא דולק תמיד ביום ובלילה:
@3 וטעם **נדב ואביהוא אלעזר ואיתמר בני אהרן** . שלא יחשב כי בהמשח האב לכהנו יהיו הבנים האלה כהונים, אבל להם בעצמם יכהן. והנה יצא פנחס ושאר הנולדים, שלא נתכהנו רק אלה הארבעה הנמשחים עמו ומולדתם אשר יולידו אחרי כן:
@4 **לכבוד ולתפארת** . שיהיה נכבד ומפואר במלבושים נכבדים ומפוארים, כמו שאמר הכתוב כחתן יכהן פאר (ישעיה סא י), כי אלה הבגדים לבושי מלכות הן, כדמותן ילבשו המלכים בזמן התורה, כמו שמצינו בכתנת ועשה לו כתנת פסים (בראשית לז ג), שפירושו מרוקמת כדמות פסים, והיא כתונת תשבץ כמו שפירשתי (לעיל כה ז), והלבישו כבן מלכי קדם. וכן הדרך במעיל וכתנת, וכתוב ועליה כתנת פסים כי כן תלבשנה בנות המלך הבתולות מעילים (ש''ב יג יח), ופירושו כי עליה כתנת פסים נראית ונגלית, כי המנהג ללבוש בנות המלך הבתולות מעילים שתתעלפנה בהן, ונמצא שכתנת הפסים עליה מלבוש עליון, ולכן אמר וכתנת הפסים אשר עליה קרעה (שם שם יט):
@4 **והמצנפת** ידועה גם היום למלכים ולשרים הגדולים, ולכן אמר הכתוב בנפול המלכות הסר המצנפת והרם העטרה (יחזקאל כא לא), וכן כתוב וצניף מלוכה (ישעיה סב ג), וכך יקראם הכתוב פארי המגבעות (להלן לט כח), וכתיב פארי פשתים יהיו על ראשם (יחזקאל מד יח), שהם פאר ושבח למכתירים בהם. והאפוד והחשן לבוש מלכות, כענין שכתוב והמניכא די דהבא על צוארך (דניאל ה טז). והציץ נזר המלכים הוא, וכתיב (תהלים קלב יח) יציץ נזרו. והם זהב וארגמן ותכלת, וכתיב (שם מה יד) כל כבודה בת מלך פנימה ממשבצות זהב לבושה, וכתיב (דניאל ה טז) ארגוונא תלבש והמניכא די דהבא על צוארך. והתכלת גם היום לא ירים איש את ידו ללבוש חוץ ממלך גוים, וכתיב (אסתר ח טו) ומרדכי יצא מלפני המלך בלבוש מלכות תכלת וחור ועטרת זהב גדולה ותכריך בוץ וארגמן, והתכריך הוא המעיל שיעטף בו:
@4 **ועל** דרך האמת, **לכבוד ולתפארת** , יאמר שיעשו בגדי קדש לאהרן לשרת בהם לכבוד השם השוכן בתוכם ולתפארת עזם, כדכתיב (תהלים פט יח) כי תפארת עזמו אתה. וכתיב (ישעיה סד י) בית קדשנו ותפארתנו אשר הללוך אבותינו, וקדשנו הוא הכבוד ותפארתנו תפארת ישראל, ועוד נאמר (תהלים צו ו) עוז ותפארת במקדשו, וכן לפאר מקום מקדשי ומקום רגלי אכבד (ישעיה ס יג), שיהיה מקום המקדש מפואר בתפארת, ומקום רגליו, שהוא מקום בית המקדש, מכובד בכבוד השם. וכן ובישראל יתפאר (שם מד כג), שיהיה מראה ומיחד בהם תפארתו, וכן אמר למטה גם בבגדי הבנים כלם לכבוד ולתפארת (להלן פסוק מ), ואמר בקרבנות יעלו על רצון מזבחי ובית תפארתי אפאר (ישעיה ס ז). והנה המזבח רצונו, והכבוד בית תפארתו. והיו הבגדים צריכין עשייה לשמן, ויתכן שיהיו צריכין כוונה, ולכן אמר **ואתה תדבר אל כל חכמי לב אשר מלאתיו רוח חכמה** (פסוק ג), שיבינו מה שיעשו. וכבר אמרו (יומא סט.) דמות דיוקנו מנצח לפני בבית מלחמתי:
@7 **והם יקחו את הזהב** . הנה כל הצואות עד כאן היו במשה עצמו, ועשית, תעשה (לעיל כו א), ועתה צוה שידבר אל כל חכמי לב שיעשו הבגדים, ולכן אמר והם יקחו את התכלת ואת הזהב, שיקבלו הנדבה מן הצבור ויעשו בה את הבגדים. והטעם לאמר, שלא ישקול להם הנדבה ולא ימנה, כי נאמנים הם, כענין שנאמר (מ''ב יב טז) ולא יחשבו את האנשים אשר יתנו את הכסף על ידם לתת לעושי המלאכה כי באמונה הם עושים:
@7 **וכאשר** נאמר בבגדים הוא הדין בכל מלאכת המשכן, כי ביום הראשון בלבד כתיב ויקחו מלפני משה (להלן לו ג), וגם הוא שלא בחשבון לקחו הכל מלפניו, ובשאר הימים הביאו אליהם, ולכך כתיב (שם ה) ויאמרו אל משה לאמר מרבים העם להביא, כי להם היו מביאים, לא שיתנום למשה והוא ישקול על ידם, אבל הם לאחר שגבו הכל מנו ושקלו ואמרו למשה כדכתיב (להלן לח כד) ויהי זהב התנופה וגו':
@30 **ולא יזח החושן** . לשון נתוק, ולשון ערבי הוא, כדברי דונש בן לבראט, לשון רש''י. והקרוב אלי כי הוא כמו יסח, מן בית גאים יסח ה' (משלי טו כה), ובוגדים יסחו ממנה (שם ב כב), ענין נתיצה ונתוק, בחלוף הסמ''ך והזי''ן, כמו יעלזו חסידים בכבוד (תהלים קמט ה), נתעלסה באהבים (משלי ז יח). ונתצתם את מזבחותם (דברים יב ג), נתסו נתיבתי (איוב ל יג). וכן ושמרתם את משמרת הבית מסח (מ''ב יא ו), מהנתץ, יזהירם שלא יפרד אחד מהם וינתץ את המשמר:
@30 **ואולי** גם כן ולמזח תמיד יחגרה (תהלים קט יט), להרס ונתיצה, יאמר שיחגור הקללה תמיד עד שיהרס וינתץ בה כאשר אחרים מתאזרים בחגורתם. אין מזח עוד (ישעיה כג י), אין הריסה עוד, יאמר לצור עברי באנשי ארצך כיאור אל ארץ תרשיש שהיתה סוחרתך, ואין הריסה ופירוד עוד, שלא יפרד אחד מכלכם משם ולא ישוב לצור כי תחרב לגמרי. הנפרד ממעמד חביריו יקרא הורס, כלשון אל יהרסו אל ה' לראות (לעיל יט כד), וכתיב ממעמדך יהרסך (ישעיה כב יט), וכן ומזיח אפיקים רפה (איוב יב כא), נתיצת האפיקים, הם הנחלים השוטפים והורסים ההרים והגאיות. ומזח בשקל מצח, שניהם בעלי הנו''ן, כי הוא מלשון נצוח, כי חוזק הראש במצח:
@32 **ונתת אל חושן המשפט את האורים ואת התומים** . סבר רבי אברהם להתחכם בענין האורים והתומים, ואמר (בפסוק ו) כי הם מעשה אומן כסף וזהב, והאריך בענינם כי חשב שהם על הצורות שיעשו בעלי הכוכבים לדעת מחשבת השואל. ולא אמר כלום. אבל הם כדברי רש''י, כתב שם המפורש (תיב''ע) נתון בין כפלי החשן, ולכך הוצרך להיות כפול (לעיל פסוק טז). והראיה, כי לא נזכרו אורים ותומים כלל במעשה האומנים, ולא הזכירם להם בצואה ולא במעשה כלל. ופרט בבגדים ויעש את האפוד (להלן לט ב), ויעש את החשן (שם ח), ולא אמר ויעש האורים והתומים, ואלו היו מעשה חרש חכם היה מאריך בהם יותר מן הכל, ואם אולי ירצה לקצר בהם לעמקם היה אומר ועשית אורים ותומים כאשר הראה אותך בהר זהב טהור תעשה אותם או כסף מזוקק:
@32 **ועוד** תשוב תראה כי לא הזכיר בה''א הידיעה אחד מכל הכלים שלא נזכרו כבר, אבל אמר ועשו ארון (לעיל כה י), ועשית שולחן (שם כג), ועשית מנורת (שם לא), וכן כלם. ובמשכן אמר ואת המשכן תעשה (שם כו א), בעבור שכבר הזכירו ועשו לי מקדש (שם כה ח). והנה באורים ותומים אמר (כאן) ונתת אל חושן המשפט את האורים ואת התומים, לא צוה אתו בעשייתם, והזכירם הכתוב בה''א הידיעה, ולא הזכירם הכתוב רק במשה לבדו, שאמר בצואה ונתת אל חשן המשפט, ובמעשה ויתן אל החשן את האורים ואת התומים (ויקרא ח ח), כי לא היו מעשה אומן ולא היה לאומנים ולא לקהל ישראל בהם מעשה ולא נדבה כלל, אבל הם סוד מסור למשה מפי הגבורה, והוא כתבם בקדושה, או היו מעשה שמים, ולכך יזכירם סתם ובידיעה, כמו וישכן מקדם לגן עדן את הכרובים (בראשית ג כד):
@32 **והנה** משה לקח כתב האורים והתומים והניחם שם בחשן המשפט אחרי שהלביש את אהרן האפוד והחשן, כמו שאמר (ויקרא ח ז ח) ויתן עליו את האפוד ויחגור אותו בחשב האפוד, וישם עליו את החשן ויתן אל החשן את האורים ואת התומים, כי לאחר כן נתנם בין כפלי החשן:
@32 **והענין** הוא, כי היו שמות קדושים, מכחם יאירו האותיות מאבני החשן אל עיני הכהן השואל במשפטם (במדבר כז כא). והמשל, כי כאשר שאלו מי יעלה לנו אל הכנעני בתחלה להלחם (שופטים א א). היה הכהן מכוין בשמות שהם האורים, והאירו לעיניו אותיות יהודה, ויו''ד מלוי, ועי''ן משמעון, ולמ''ד מלוי, וה''א מאברהם הכתוב שם על דעת רבותינו (יומא עג:). או שהאירה פעם אחרת לנגד עיניו ה''א מיהודה. והנה כאשר האותיות מאירות אל עיני הכהן עדין לא ידע סדורן, כי מן האותיות אשר סדרו מהן יהודה יעלה היה אפשר להעשות מהם ''הוי הד עליה'', או ''הי על ידוהה'', ותיבות אחרות רבות מאד, אבל היו שם שמות הקדש אחרים נקראים ''תומים'', מכחם יהיה לב הכהן תמים בידיעת ענין האותיות שהאירו לעיניו. כי כאשר כיון בשמות האורים והאירו, חוזר מיד ומכוון בשמות התומים. ועודם האותיות מאירות לעיניו, ויבא בלבו שחבורם יהודה יעלה. וזאת מדרגה ממדרגת רוח הקדש, היא למטה מן הנבואה, ולמעלה מבת קול שמשתמשים בה בבית שני לאחר שפסקה הנבואה ופסקו אורים ותומים כמו שהזכירו רבותינו (שם כא:):
@32 **ואפשר** שאחרי שנתן משה בחשן השמות הקדושים של האורים והתומים היו נודעים במסורת ממנו לגדולי חכמי ישראל שמסרם להם עם סתרי תורה, ולפיכך היה ביד דוד אפוד (ש''א כג ו), והיה כדמות אפוד משה, ובו חשן כדמות חשן הקדש, אבל נראה שהיו בד, כאשר נאמר בשמואל (שם ב יח) נער חגור אפוד בד, ואמר בנוב עיר הכהנים (שם כב יח) שמונים וחמשה איש נושא אפוד בד, וילבישו אותו את הכהן שהוא מבני הנביאים ושואלים בו ונענין לפעמים, כאשר חשב בזה ר''א. ומה שאמר שאלו ראה תשובת רבינו האיי לא אמר ככה, כבר ראינוה וחשבנוה, וידענו כי ר''א לא נתכון אליה:
@33 **מעיל** . כתב רש''י (לעיל בפסוק ד) הוא כמין חלוק, וכן הכתנת, אלא שהכתנת סמוך לבשרו ומעיל קורא חלוק העליון. ואין הדבר כן, כי המעיל בגד יתעטף בו, כמו שאמר (ש''א כח יד) והוא עוטה מעיל, וכתיב (ישעיה סא י) מעיל צדקה יעטני, ולא תבא עטיה על הכתנת רק על השלמה אשר יכסה בו, דכתיב (תהלים קד ב) עוטה אור כשלמה, כי הוא עטוף, וכן ועל שפם יעטה (ויקרא יג מה), יתעטף. והוא תרגומו של יונתן בן עוזיאל שהזכיר הרב (רש''י לעיל בפסוק ד) כרדוטין (ס''א כדרוניא, כרדונין) (ש''ב יג יח), כי הוא עטוף קרוב לצורת האפוד שיתעטף בו חצי הגוף שכלפי רגליו, כי אם הי' חלוק אינן דומין זה לזה כלל. וראיה עוד שאמר ויחזק בכנף מעילו ויקרע (שם א טו כז), והנה יש לו כנפים ואינו כמין חלוק. אבל המעיל כסות מקיף את הגוף כלו מצוארו ולמטה עד רגלי האדם ואין לו בית יד כלל, ובשאר המעילים יש לו בית צואר כנגד כל הצואר תפור בו, ואותו בית צואר נקרא פי מעיל, וצוה הכתוב שיהא ארוג עמו. והמעיל כלו מחולק מלפניו עד למטה, מכניס ראשו בנקב פיו ונמצא צוארו חגור בפי המעיל, ומלפניו שתי כנפים מכסה בו ומגלה כרצונו, כמין גלימא שאין לה בית ראש, שחלקו התפירה שלפניה מקמי שפה ולמטה, ולכן יבא בו לשון עטיה לעולם:
@33 **ולא** ידעתי גם כן למה עשה הרב הפעמונים לעצמם, פעמון בין שני רמונים, כי אם כן לא היו הרמונים משמשין כלום, ואם לנוי, למה היו עשויים כרמונים חלולים, יעשם כמין תפוחי זהב. ועוד, שהיה צריך הכתוב לפרש במה יתלה הפעמונים, ואם יעשה בהם טבעות לתלות בהן:
@33 **אבל** הם בתוכם ממש, כי הרמונים חלולים ועשויים כמין רמונים קטנים שלא פתחו פיהם, והפעמונים טמונים בהם ונראים מתוכם. ולא פירש הכתוב מנינם, אבל רבותינו אמרו שהיו שבעים ושנים זגין, ובהם שבעים ושנים ענבלין, ותולה שלשים וששה מצד אחד, ושלושים וששה מצד אחר, כדאיתא בזבחים בפרק המזבח (פח:), ומכאן תלמוד שאינו כמין חלוק וכתנת, אלא יש לו כנפים:
@33 **וכן** כתב רש''י (לעיל בפסוק ד) שהמצנפת כמין כובע, שהרי במקום אחר (להלן בפסוק מ) קורא להם מגבעות, ומתרגמינן קובעין. וגם זה אינו, שהרי אמרו שהמצנפת ארכה שש עשרה אמה, והרי הוא כעין צניף שצונף בו את ראשו, מגלגל ומחזיר מגלגל ומחזיר סביב ראשו כפל על כפל. ומצנפת של כהן גדול אינה קרויה מגבעת בשום מקום, אבל בכהן הדיוט אמר הכתוב מגבעות (להלן כח מ, כט ט, ועוד), ואף היא מצנפת היא, אלא שקושר בה כל ראשו ומעלה הכפלים עליו כעין מגבעת שהוא קובע כדברי אונקלוס, כי מגבעת כמו מקבעת, כאשר אמרתי בסדר ויהי מקץ (בראשית מא מז) בחלופי הגימ''ל והקו''ף, אלא שהמגבעת כמו המצנפת, ולכך הזכירו חכמים תדיר בכהן גדול והדיוט מצנפת בתורת כהנים (צו ב א), ובמסכת יומא (עא:) שנינו כהן גדול משמש בשמונה כלים וההדיוט בארבעה, בכתנת ומכנסים מצנפת ואבנט, מוסף עליו כהן גדול, חשן ואפוד ומעיל וציץ:
@37 **ולא ימות** . מכלל לאו אתה שומע הן, אם יהיו עליו לא יתחייב מיתה, הא אם יכנס מחוסר אחד מן הבגדים הללו חייב מיתה. לשון רש''י. ואינו נכון בעיני, שהיה לו לכתוב פסוק זה לאחר שיזכיר כל שמונה בגדים (אחרי פסוק מב), ולמה הזכיר זה בשלשה בגדים חשן ואפוד ומעיל קודם שיזכיר ציץ וכתנת מצנפת ואבנט ומכנסים. וכן אמר **ובצאתו ולא ימות** , ואין ביציאה עבודה שיתחייב עליה משום מחוסר בגדים. וכן והיו על אהרן ועל בניו (פסוק מג) כתב רש''י והיו כל הבגדים האלה על אהרן ועל בניו הראויים לו והאמורים בהם, ומתו, הא למדת שהמשמש מחוסר בגדים חייב מיתה. וכן נראה זה בדרך הפשט:
@37 **אבל** לפי העולה מן הסוגיות שבגמרא אין דעת רבותינו כן, אבל אצלם המצוה הזאת שוה בכולם, באהרן ובבניו, והיא על המכנסים, והענש גם כן בהם. כי צוה בעשייה ועשה להם מכנסי בד (פסוק מב), וצוה על הלבישה והיו על אהרן ועל בניו (פסוק מג), כי בשאר הבגדים צוה למעלה בעשייתם (מפסוק ב עד פסוק מ) וצוה בלבישה (בפסוק מא) והלבשת אותם את אהרן אחיך ואת בניו אתו, א''כ הצואה הזו (בפסוק מג) כולה על המכנסים, ועליהן יהיה העונש:
@37 **ולמדנו** זה ממה שאמרו בסנהדרין (פג:) ובשחיטת קדשים (זבחים יז:) מחוסר בגדים ששימש מנא לן דבמיתה, א''ר אבהו א''ר יוחנן, ומטו בה משמיה דר' אלעזר ברבי שמעון, וחגרת אותם אבנט וחבשת להם מגבעות והיתה להם כהונה לחקת עולם (להלן כט ט), בזמן שבגדיהם עליהם כהונתם עליהם, אין בגדיהם עליהם אין כהונתם עליהם והוו להם זרים, ואמר מר זר ששימש במיתה. ואם היה הכתוב הזה (פסוק מג) אצלם בכל הבגדים הנה בכאן עונש מפורש למחוסר בגדים, כמאמר הרב, אבל היא במכנסים בלבד, והכתוב האחר (להלן כט ט) בשאר הבגדים, ולא הוזכרו שם המכנסים. והראיה על דעתם שלא הזכיר למטה (להלן כט ה ט) בסדר הלבישה מכנסים כלל, כי בעבור שענש עליהם בכאן אין צורך לחזור ולהזכירם, כי בידוע שילבשם:
@37 **ומה** שאמר למעלה (כאן) **ונשמע קולו בבואו אל הקדש ולא ימות** , הוא על דעתי ביאור למצות הפעמונים, כי מפני שאין בהם צורך בלבישה, ואין דרך הנכבדים לעשות להם כן, לכך אמר כי צוה בהם בעבור שישמע קולו בקדש, ויכנס לפני אדוניו כאלו ברשות, כי הבא בהיכל מלך פתאום חייב מיתה בטכסיסי המלכות, כענין אחשורוש (אסתר ד יא):
@37 **וירמוז** למה שאמרו במסכת יומא ירושלמי (א ה) וכל אדם לא יהיה באהל מועד (ויקרא טז יז), אפילו אותן שכתוב בהן ודמות פניהם פני אדם (יחזקאל א י) לא היו באוהל מועד, על כן צוה להשמיע קולו כמי שיקרא הוציאו כל איש מעלי, ויבא לעבוד את המלך ביחוד, וכן בצאתו, לצאת ברשות, ושיודע הדבר כדי שיוכלו משרתי המלך לשוב לפניו. ובפרקי היכלות ידוע זה הענין. והנה הטעם שלא יפגעו בו מלאכי אלהים. והזהיר זה בכ''ג למעלתו, וזה טעם לפני ה', כי הוא העובד לפניו שתשרה שכינתו בעבודתו כי מלאך השם צבאות הוא (מלאכי ב ז), כי ההדיוטים (לא) יכנסו בהיכל להקטיר ולהטיב:
@37 **וראיתי** במדרש ואלה שמות רבה (לח ח) באבני החשן מה טעם, שיהא הקב''ה מסתכל בהן בבגדי הכהן בכניסתו ביום הכפורים ונזכר לזכות השבטים. רבי יהושע בשם רבי לוי אומר, משל לבן מלכים שהיה פדגוג נכנס אצלו מלמד על בנו סניגוריא, והיה מתירא מן העומדים עליו שמא יפגעו בו, מה עשה הלבישו פורפירא שלו שיהיו רואין אותו ומתיראין ממנו, כך אהרן היה נכנס בכל עת (ויק''ר כב ו) לבית קדש הקדשים, ואלולי זכיות הרבה שהיו נכנסות עמו ומסייעות אותו לא היה יכול ליכנס למה שהיו מלאכי השרת שם, מה עשה הקב''ה נתן לו מדמות לבושי הקדש, שנאמר (ישעיה נט יז) וילבש צדקה כשרין. עד כאן אגדה זו. ואע''פ שלא היה נכנס לפני ולפנים בבגדים אלו, אף באהל מועד הוצרך לכך ביום הכפורים, שהרי כתיב (ויקרא טז יז) וכל אדם לא יהיה באהל מועד:
@39 **על פתיל תכלת** . ובמקום אחר (להלן לט לא) הוא אומר **ויתנו עליו פתיל תכלת** . ועוד, כתיב כאן **והיה על המצנפת** , ולמטה הוא אומר **והיה על מצח אהרן** , ובשחיטת קדשים (זבחים יט.) שנינו שערו היה נראה בין ציץ למצנפת ששם היה מניח תפילין, למדנו שהמצנפת למעלה בגובה הראש, [ואינה עמוקה להכנס בה כל הראש עד המצח], והציץ מלמטה, [וג' נקבים היה עושה בו, בשני ראשיו ואמצעיתו], והפתילים היו בנקבים ותלויים בו בשני ראשיו ובאמצעו, ששה בשלשה מקומות הללו, פתיל מלמעלה אחד מבחוץ ואחד מבפנים כנגדו, וקושר ראשי הפתילים מאחורי העורף שלשתם, נמצאו בין אורך הטס ופתילי ראשיו מקיפין את הקדקד, והפתיל האמצעי שבראשו קשור עם ראשי השנים, הולך על פני רוחב הראש מלמעלה, ונמצא עשוי כמין כובע, ועל פתיל האמצעי הוא אומר והיה על המצנפת, והיה נותן את הציץ על ראשו, וע''י פתיל האמצעי הוא מחזקו שאינו נופל, והטס תלוי כנגד מצחו, הרי נתקיימו כל המקראות הללו, פתיל על הציץ (להלן לט לא), וציץ על הפתיל (כאן), ופתיל על המצנפת מלמעלה (כאן ושם). כל זה לשון רש''י:
@39 **ואני** תמה בדבריו, שהכתוב אינו מצוה רק לעשות פתיל תכלת אחד, והוא עושה ששה. ועוד, שהוא מצרף המקראות של הצואה והעשייה, ומרבה פתילים כנגד כלן, וכן תוכל למנות בארון ושולחן ומנורה. ואם הכתוב צוה שישימו אותו על פתיל תכלת, היאך נתנו הם עליו פתיל תכלת, ואנה צוו לעשות כן. ומה צורך לחוטין שבאמצע, והוא קשור מאחורי העורף כדרך כל ציץ באנשים ובנשים:
@39 **אבל** אין הדבר כמו שאמר הרב, ולא היה שם אלא פתיל אחד, שהטס מקיף מאזן לאזן, ונקוב בשתי קצותיו, ופתיל תכלת נכנס בשני הנקבים, והציץ נקשר בו כנגד העורף. והנה היה צונף המצנפת סביב הראש, לא על המצח כלל, אלא למעלה במקום שער. ועל דעת רבותינו (זבחים יט.) היה מניח גם מקצת שער ראשו כנגד פניו לתפילין. והיתה הצניפה בגובה שבראש כנגד המוח האמצעי, והוא מכסה בה כל הראש כנגד אחוריו. והרי הצניפה בגובה שבראש כנגד המוח בשפוע, ומניח הציץ כנגד מצחו מאזן לאזן, ואין הפסק בין מצחו לציץ. אבל מאוזן לאוזן מאחוריו כנגד כל העורף תהיה המצנפת, והפתיל שנקשר בו, יבא עליה:
@39 **וזהו** שאמר **ושמת אותו על פתיל תכלת** , שיכניס הפתיל בנקבי הציץ, והיה הפתיל על המצנפת לאחורי אזניו כנגד העורף, **אל מול פני המצנפת יהיה** הציץ, **והיה על מצח אהרן** , ויהיה על המצח כנגד המצנפת בפניו. וזהו שאמר (להלן כט ו) ושמת המצנפת על ראשו, כלומר למעלה בעליון שבראש, לא כמו המגבעות שנאמר בהן (שם ט) וחבשת להם מגבעות, שהן חובשות הראש כמי שחושש בראשו וחובשו לחזוק. ואומר (שם ו) ונתת את נזר הקדש על המצנפת, כי עליה יקשרנו מאחוריו. וכן אמר (להלן לט לא) ויתנו עליו פתיל תכלת לתת על המצנפת מלמעלה, כי שם ינתן בקשר. וכן וישם על המצנפת אל מול פניו את ציץ הזהב (ויקרא ח ט), ששם בקשירתו על המצנפת, ואל מול פניו ציץ הזהב. והנה הנתינה בכל הכתובים על המצנפת, כי היא הקשירה, אבל הציץ אל מול פני המצנפת במצח:
@39 **ואין** להקפיד בין ויתנו עליו פתיל תכלת (להלן לט לא), ובין ושמת אותו על פתיל תכלת (כאן), כי בשניהם כאלו אומר ושמת אותו בפתיל תכלת, ויתנו בו פתיל תכלת, כדרך ונתת אותם על סל אחד (להלן כט ג), בסל, וכמוהו המלט על נפשך (בראשית יט יז). או ישמש במקום ''אל'', ונתת אותו אל פתיל תכלת, ויתנו אליו פתיל תכלת. כי הפתיל נתן אליו, והוא אל הפתיל, כי בו יסמך:
@39 **והכלל** שאין ענין הכתובים אלא שיכניסו הפתיל בנקבי הציץ, וגם כן הוא שהציץ על הפתיל והפתיל על הציץ, וכן וירכסו את החשן מטבעותיו אל טבעות האפוד בפתיל תכלת (לעיל פסוק כח) שהביא רש''י ראיה ממנו, פתיל אחד הוא, שהיו מכניסין פתיל אחד בטבעות החשן ובטבעות האפוד שכנגדו, וכן בקצה האחר פתיל אחד, כי שני מקומות הן וכל אחד בפתיל אחד ירכסו אותו:
@43 **והלבשת אותם את אהרן אחיך ואת בניו אתו** . אותן הכתובים בהם. לשון רש''י. וטעם אתו, שביום אחד ילבישם כלם וימשחם:
@43 **ומשחת אותם ומלאת את ידם** . כל מלוי ידים לשון חנוך, כשהוא נכנס להיות מוחזק בו מאותו היום והלאה. לשון רש''י. ולא הבינותי בדבריו איך יבא לשון מלוי ידים לחנוכת כל דבר. ומה שאמר הרב כי בלשון לעז כשממנין אדם על פקודת דבר נותן השליט בית יד של עור שקורין גונ''ט, ועל אותו בית יד הוא מחזיקו בדבר והוא מלוי ידים, לא ידעתי אם ירצה הרב לומר שעל שם הבית יד יקרא החנוך מלוי ידים, ויביא ראיה מן המנהג, ודע כי הענין ההוא יצא להם מן התורה שהוא אצלם קנין החליפין של בועז, וכך מתורגם להם שלף איש נעלו (רות ד ז), ששולף הגנ''ט שלו, והם אומרים שהגואל נתן לבועז, וזה מנהגם הוזכר בספרי חכמיהם. והנה דברנו בדברי הבאי:
@43 **והנכון** בלשון מלוי ידים בתורה שהוא לשון שלמות, כלשון כי מלאו ימי (בראשית כט כא), ובמלאת הימים האלה (אסתר א ה), עד יום מלאת (ויקרא ח לג), בהשלימם, וכן בכסף מלא (בראשית כג ט), מחיר שלם. והטעם, כי הזר אשר לא תשיג ידו בטהרתו להקריב קרבן או לעבוד עבודת המלכות הנה ידו חסרה בעבודה ההיא, וכאשר יכשר לעשות כן הנה ידו שלימה, ראויה לכל העבודות והמלאכות. וכן מלאו ידכם היום (להלן לב כט), כי עתה ידיכם מלאה בכל עבודת השם, כי איש בבנו ובאחיו עבדתם אותו. או שירמוז להם כי בזכות זה יהיו נבחרים לעבוד עבודת ה' במשכן, כמו שאמר בעת ההיא הבדיל ה' את שבט הלוי (דברים י ח):
@43 **ודוד** המלך אמר לישראל בנדבת הבית ברצותי בבית אלהי יש לי סגלה זהב וכסף נתתי לבית אלהי, ואמר להם ומי מתנדב למלאת ידו היום לה' (דהי''א כט ה), כי בהתנדבם לבנין הבית תהיה ידם שלימה בכל הקרבנות ובכל העבודות, כי אין עבודת ישראל להקב''ה שלימה אלא בבית המקדש. וכן איל המלואים בפרשה הזאת (להלן כט כב) שמלוי הכהנים בו, כי חטאת והעולה לכפר, וזה למלאת ידו בהקרבה:
@43 **ומצאתי** בתרגום הירושלמי שתרגם איל המלואים דאשלמותא (כ''ה בתרגום יונתן ויקרא ח כב), וכן תרגם בכולם לשון שלמות. אבל אונקלוס רדף הענין ולא הקפיד בלשון, כמנהגו במקומות רבים:
@43 **ויש** מפרשים (הרד''ק בספר השרשים שרש מלא) ומלאת את ידם, שימלא ידם מן הקרבנות, וכן החפץ ימלא את ידו (מ''א יג לג), שיקריב מהן כרצונו מלא ידיו. והנכון מה שפרשתי. ופירוש החפץ ימלא את ידו ויהי כהני במות (שם), שיביא מלואים לו בקרבן כאשר בדא מלבו לחנכו, ואחרי כן יהיה כהן לבמות, כי בדומה לדרכי התורה יעשו:
@48 (ג~ד) **והקרבת אותם בסל** נמשך לפניו, יאמר כי הלחם בסל והפר והאילים ואהרן ובניו יקריבו אל פתח אוהל מועד. ורחצת אותם במים, לאהרן ובניו. ויותר נכון כי **והקרבת אותם בסל** . לא יפרש, כי מן הסתם הוא ידוע שיקריבם אל המקום אשר יצוה לבא הכהנים, והכתוב השני ידבר על אהרן ועל בניו, ולכך אמר ורחצת אותם במים:
@52 **ולקחת את שמן המשחה ויצקת על ראשו** . אמר ר''א כי זה לפני שומו המצנפת על ראשו, כי על ראש עצמו יצוק השמן. ואיננו נכון בעיני, כי גם במעשה אמר וישם את המצנפת על ראשו וגו' (ויקרא ח ט), ואח''כ אמר ויקח את שמן המשחה וימשח את המשכן וגו' (פסוק י), ואח''כ ויצק משמן המשחה על ראש אהרן (פסוק יב). אבל הנכון שהיתה הצניפה סביב סביב ואמצע הראש מגולה ועליו יצק השמן. ואם היתה המשיחה בכל הראש כדברי רש''י, תהיה היציקה במקום הנחת תפילין שהיה מניח מגולה, ומשם ימשכנו כמין כף יונית:
@54 **וחגרת אותם אבנט** . ירמוז לאהרן ובניו, ושב לפרש אהרן ובניו, כמו יביאה את תרומת ה' (להלן לה כד), אשר לא יעבדו אותו את נבוכדנאצר (ירמיה כז ח). כדברי רבי אברהם. ואם כן יחזור וחבשת להם מגבעות למקצתם, כי אהרן אין לו מגבעת, והמצנפת כבר היא על ראשו. ויתכן שיהיה שיעור הכתוב וחגרת אותם אבנט ואהרן ובניו, יאמר, תחגור בניו הנזכרים אבנט, ואהרן עצמו עם בניו. ובעבור שהאבנט שוה בכולם (יומא יב.) לא הוזכר עם בגדי אהרן למעלה (בפסוקים ה ו), והוצרך עתה לומר שיחגרנו אבנט כבניו. ולא הזכיר המכנסים, כי לא הוצרך, כאשר פירשתי (לעיל כח לה):
@54 **והטעם** שהפריש המכנסים משאר הבגדים, כי כל הבגדים היה משה מלביש אותם כמו שצוה (בפסוק הקודם) והלבשתם, אבל המכנסים שהם לכסות בשר הערוה (שם שם מב) היו הם לובשים אותם בהצנע, ולכן לא הזכיר עתה בכלל ולקחת את הבגדים והלבשת, ולפיכך הפרישם במצוה ובענש, כמו שהזכרתי למעלה (שם לה):
@55 **והקרבת את הפר לפני אהל מועד** . אמר ר''א כי טעמו כאשר תקריב את הפר לפני אהל מועד יסמוך אהרן ובניו עליו, כי כבר הזכיר זה למעלה (בפסוק ג). והנכון בעיני כאשר פירשתי (שם), ששם יצוה להקריבם, ולא פירש אל אהל מועד, רק שיקריב אותם, והטעם שיקריבם אל מקום הכהנים שיהיו מזומנים, ודי שיהיו לפני פתח חצר המשכן, ועכשיו הצריך שיקריבם לפני אהל מועד אל פתח האהל כאשר יפרש בשחיטה (בפסוק הבא), כי הסמיכה תהיה שם:
@58 **החלב המכסה את הקרב** . הוא הקרום שעל הכרס שקורין טילא. לשון רש''י. ולפי דעתי כי החלב המכסה את הקרב הוא הקרום, אבל כאשר יאמר כל החלב המכסה את הקרב ירמוז לשני חלבים אשר שם, לחלב הקרום הזה, ולחלב הגס אשר על הקרב, כמו שנאמר בסדר ויקרא (ג ג) ואת החלב המכסה את הקרב ואת כל החלב אשר על הקרב. והנה על הקרב שני חלבים, פעם יזכיר הכתוב את שניהם, ופעמים יכלול אותם כאחד במלת כל. והנה בכאן בכל החלב המכסה את הקרב כלל גם החלב אשר על הקרב, ושם במעשה הצואה הזאת אמר ויקח את כל החלב אשר על הקרב ואת יותרת הכבד (שם ח טז), כללם בכל החלב אשר על הקרב. ולמטה בפרשה זו (בפסוק כב) אמר ולקחת מן האיל החלב והאליה ואת החלב המכסה את הקרב, והראשון המוזכר סתם הוא החלב אשר על הקרב:
@59 **תשרף באש** . לא מצינו חטאת חיצונה נשרפת אלא זו. לשון רש''י. והוראת שעה היתה כדברי רבותינו. והטעם בזה, שהכל גלוי לפניו, והיה פר חטאת זה לכפר על מעשה העגל, וקרבנו של כהן משיח הוא (ויקרא ד ג). ושם (שם ד ו) יצוה להביא את דמו אל מבית לפרכת, ולא רצה עתה להכניסו שם לפנים, כי שם (ד ו) אמר בטעם את פני פרכת הקדש, וכאן עדיין לא נתקדש ולא שרתה עליו שכינה שיקרא פרכת הקדש, והנה החיצון כפנימי. והסמיכה בבניו, מפני שהתאנף על אהרן להשמידו (דברים ט כ) והוא כלוי בנים (ויק''ר ז א), הוצרכו גם הם להתכפר בו. וטעם השריפה כטעם שריפת פרה אדומה, וסודה ידוע מן השעיר המשתלח:
@71 **מאיל המלואים אשר לאהרן** . לא הזכיר בניו, והאיל הוא מלואים לכלם, והטעם, כי יצוה הכתוב **ולקחת את חזה התנופה מאיל המלואים** בעבור שהוא לאהרן, ואין החזה ראוי לו, כי לא יהיה לבעלים. ואחר שנתן טעם שאינו ראוי שיהיה לאהרן אין צורך לומר שלא יהיה לבניו, כי אחריו יזכו הם. ולמטה אמר (בפסוק כז) מאשר לאהרן ומאשר לבניו, כלומר כאשר לוקח מקרבן כלם החזה ושוק, כן יקחו הם האב והבנים מקרבנות המקריבים על ידם:
@74 **למשחה בהם** . להתגדל בהם, שיש משיחה שהיא לשון שררה, כמו לך נתתים למשחה (במדבר יח ח), אל תגעו במשיחי (תהלים קה טו). לשון רש''י. ואולי כן הוא, כי בעבור ששררת ישראל למשוחים היא, למלך ולכ''ג, ישאילו הלשון לכל שררה. וכן ומשחת את חזאל למלך על ארם, ואת אלישע בן שפט תמשח לנביא תחתיך (מ''א יט טו טז). אבל בכאן הנכון הוא למשחה בהם, למשוח בבגדים הכהנים הגדולים מבניו, ולמלא בם את ידם להקריב הקרבנות. וכן לך נתתים למשחה (במדבר יח ח), שנתתים להיות שלך בעבור שמשחתיך לכהן לי, וכן אל תגעו במשיחי (תהלים קה טו), כי הנוגע בהם נוגע במשיחי ה' העתידים לצאת מהם, כמו שאמר ומלכים מחלציך יצאו (בראשית לה יא), מלכי עמים ממנה יהיו (שם יז טז):
@74 **ויתכן** שנאמר עוד כי ומשחת את חזאל למלך על ארם, שישלח לו שמן למשחו למלך להודיעו כי דבר ה' הוא, ועשה כן אלישע במצות רבו כאשר הגיד לו שימלוך (מ''ב ח יג) ואע''פ שלא נכתב שם, ומשח את אלישע לנביא. ואולי כן עשו בכורש אשר משחוהו כמלכי ישראל, בעבור שידע כי נביא בישראל המליך אותו ויקרא את שמו בעבור ה'. ולכך אמר למשיחו לכרש (ישעיה מה א). ורבותינו אמרו (מגילה יב.) וכי כרש משיח הוא וכו'. והנה כולן משיחות ממש. והכתוב שאמר (ישעיה סא א) רוח ה' אלהים עלי יען משח ה' אותי לבשר ענוים, דרך משל, שימשיל רוח הקדש אשר תחול עליו לשמן הטוב, כענין טוב שם משמן טוב (קהלת ז א):
@76 **ובשלת את בשרו במקום קדש** . לא ידענו אם הוראת שעה היא שיהא בשר המלואים טעון כהן בבשולו, או יהיה ובשלת בצווי, כמו ומטך אשר הכית בו את היאור (לעיל יז ה), ויבן שלמה את הבית (מ''א ו יד), כדברי רבי אברהם. והצריך במקום קדוש, שהן כזבחי שלמי צבור שנאכלין לפנים מן הקלעים ונאכלין ליום ולילה עד חצות (זבחים ה ה):
@81 **תעשה ליום על הכפורים** . בשביל הכפורים, לכפר על המזבח מכל זרות ותיעוב. ובמדרש תורת כהנים (צו א טו) אומר כפרת המזבח הוצרכה שמא התנדב אדם דבר גזל במלאכת המשכן והמזבח. לשון רש''י. והנכון כי על הכפורים על שני האילים שהם כפורים לאהרן ולבניו, כמו שאמר כאן (לעיל בפסוק לג) ואכלו אותם אשר כפר בהם, ואף כי החטאת כפרה, וכתיב כאשר עשה ביום הזה צוה ה' לעשות לכפר עליכם (ויקרא ח לד), כדברי ר''א:
@91 **לשכני בתוכם** . על מנת לשכון בתוכם. לשון רש''י. ושמוש הלמ''ד בתנאי כזה איננו נמצא. ויתכן שיאמר וידעו בשכני בתוכם כי אני ה' אלהיהם אשר הוצאתי אותם מארץ מצרים, כי ידעו כבודי ויאמינו שאני הוצאתי אותם מארץ מצרים. והוא כדרך ויהי דוד לכל דרכיו משכיל (ש''א יח יד), כי בוחר אתה לבן ישי (שם כ ל), על אשר מריתם את פי למי מריבה (במדבר כ כד), והדומים להם. אבל רבי אברהם אמר כי לא הוצאתי אותם מארץ מצרים רק בעבור כי אשכון בתוכם, וזהו תעבדון את האלהים על ההר הזה (לעיל ג יב). ויפה פירש:
@91 **ואם** כן יש בענין סוד גדול, כי כפי פשט הדבר השכינה בישראל צורך הדיוט ולא צורך גבוה, אבל הוא כענין שאמר הכתוב ישראל אשר בך אתפאר (ישעיה מט ג), ואמר יהושע ומה תעשה לשמך הגדול (יהושע ז ט), ופסוקים רבים באו כן, אוה למושב לו (תהלים קלב יג), פה אשב כי אויתיה (שם יד), וכתוב והארץ אזכור (ויקרא כו מב):
@92 **ועשית מזבח מקטר קטורת** . הנה מזבח הקטרת מן הכלים הפנימיים היה, ראוי שיזכירנו עם השולחן והמנורה שהוא מונח עמהם, וכן הזכירם במעשה בפרשת ויקהל (להלן לז כה), אבל הטעם להזכירו כאן אחר המשכן וכל כליו והקרבנות, בעבור שאמר בתשלום הכל ונקדש בכבודי (לעיל כט מג), ושכנתי בתוך בני ישראל (שם מה), אמר כי עוד יתחייב להם שיעשו מזבח מקטר קטרת להקטיר לכבוד השם. וזהו רז שנמסר למשה רבינו שהקטרת עוצרת המגפה (שבת פט.), כי הקטרת במדת הדין (זוה''ק ויקרא יח), שנאמר ישימו קטורה באפך (דברים לג י), מן וחרה אפי (שם לא יז), והוא מה שאמר בקטרת זרה ועל פני כל העם אכבד (ויקרא י ג), שידעו כבודי כי לא ישא לפשעכם ויזהרו בכבודי. ולכך אמר כאן (בפסוק ו) ונתת אותו לפני הפרכת אשר על ארון העדות לפני הכפורת אשר על העדות אשר אועד לך שמה, כי מה צורך להאריך בכל אלה ולא אמר ונתת אותו לפני ארון העדות באהל מועד, כאשר אמר בפרשת פקודי (להלן מ ה), אבל הוא להורות על ענינו:
@98 **והקטיר עליו אהרן** . אין המצוה הזו בכהן גדול בלבד, אלא היא אף בכהנים הדיוטים כדין הדלקת הנרות שבצדה (בפסוק הבא) שאמר ג''כ ובהעלות אהרן את הנרות, ואינה בכ''ג בלבד כמו שאמר למעלה (כז כא) יערוך אותו אהרן ובניו. ולא ידעתי למה הזכיר אהרן בשניהם ולא אמר הכהן, ואולי מפני שיטת הכתוב למטה וכפר אהרן על קרנותיו (להלן פסוק י) שהוא באהרן בלבד. או שירמוז שאהרן יתחיל בקטרת ובנרות. וכן אמר בסוף אמור אל הכהנים (ויקרא כד ג) יערוך אותו אהרן ולא הזכיר בניו, בעבור שהוא יתחיל בה. והזכיר שם חקת עולם במצוה:
@100 **קטרת זרה** . שום קטרת של נדבה, שכולן זרות לו חוץ מזו. לשון רש''י. אבל אונקלוס אמר קטורת בוסמין נוכראין, ולא תרגם נוכריתא, רצה לפרש שלא יעשה קטרת מסמים אחרים זולתי הקטרת אשר יצוה אותם, וכן אם הוסיף בה סמים אחרים יעבור בלאו הזה:
